// {PM}
// - Добавлен метод без префикса Подключаемый_ВыполнитьКомандуИнтеграции. При обновлении формы не отмечать к удалению.
// {/PM}

&НаСервере
&После("ПриСозданииНаСервере")
Процедура упо_ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	// {PM}
	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец ИнтеграцияС1СДокументооборотом
	// {/PM}

КонецПроцедуры

&НаКлиенте
Процедура Подключаемый_ВыполнитьКомандуИнтеграции(Команда)
	// {PM}
	// ИнтеграцияС1СДокументооборотом
		ИнтеграцияС1СДокументооборотБазоваяФункциональностьКлиент.ВыполнитьПодключаемуюКомандуИнтеграции(Команда, ЭтотОбъект, Элементы.Список);
	// Конец ИнтеграцияС1СДокументооборотом
	// {/PM}
КонецПроцедуры

&НаСервере
&После("ПриСозданииНаСервере")
Процедура упо_ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)
	// {PM}
	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец ИнтеграцияС1СДокументооборотом
	// {/PM}

КонецПроцедуры

&НаСервере
Процедура упо_ПередЗаписьюНаСервере(Отказ, ТекущийОбъект, ПараметрыЗаписи)

	// {PM}
	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПередЗаписьюНаСервере(ЭтотОбъект, ТекущийОбъект, ПараметрыЗаписи);
	// Конец ИнтеграцияС1СДокументооборотом
	// {/PM}

КонецПроцедуры

&НаКлиенте
Процедура Подключаемый_ВыполнитьКомандуИнтеграции(Команда)
// {PM}
// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональностьКлиент.ВыполнитьПодключаемуюКомандуИнтеграции(Команда, ЭтотОбъект, Объект);
// Конец ИнтеграцияС1СДокументооборотом
// {/PM}
КонецПроцедуры

&НаСервере
&После("ПриСозданииНаСервере")
Процедура упо_ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	// {PM}
	упо_УправлениеДоступом.ГруппыДоступаПриСозданииНаСервере(ЭтотОбъект, Отказ, СтандартнаяОбработка)
	// {/PM}

КонецПроцедуры

&НаСервере
&После("ПриЧтенииНаСервере")
Процедура упо_ПриЧтенииНаСервере(ТекущийОбъект)

	// {PM}
	упо_УправлениеДоступом.ГруппыДоступаПриЧтенииНаСервере(ЭтотОбъект, ТекущийОбъект)
	// {/PM}

КонецПроцедуры

&НаСервере
&После("ПослеЗаписиНаСервере")
Процедура упо_ПослеЗаписиНаСервере(ТекущийОбъект, ПараметрыЗаписи)

	// {PM}
	упо_УправлениеДоступом.ГруппыДоступаПослеЗаписиНаСервере(ЭтотОбъект, ТекущийОбъект, ПараметрыЗаписи)
	// {/PM}

КонецПроцедуры

&НаКлиенте
&После("ВидыДоступаПриАктивизацииСтроки")
Процедура упо_ВидыДоступаПриАктивизацииСтроки(Элемент)

	// {PM}
	упо_УправлениеДоступомКлиент.ВидыДоступаПриАктивизацииСтроки(ЭтотОбъект, Элемент);
	// {/PM}

КонецПроцедуры

&НаКлиенте
Процедура упо_ЗначенияДоступаВыбор(Элемент, ВыбраннаяСтрока, Поле, СтандартнаяОбработка)
	// {PM}
	упо_УправлениеДоступомКлиент.ЗначенияДоступаВыбор(ЭтотОбъект, Элемент, ВыбраннаяСтрока, Поле, СтандартнаяОбработка)
	// {/PM}
КонецПроцедуры

&После("ПередЗаписью")
Процедура упо_ПередЗаписью(Отказ)
	// {PM}
	упо_ОбработчикиСобытийВызовСервера.обСправочникОбъектПередЗаписью(ЭтотОбъект, Отказ);
	// {/PM}
КонецПроцедуры

&НаСервере
&После("ПриСозданииНаСервере")
Процедура упо_ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	// {PM}
	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец ИнтеграцияС1СДокументооборотом
	// {/PM}

КонецПроцедуры

&НаСервере
&После("ПриСозданииНаСервере")
Процедура упо_ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)
	// {PM}
	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец ИнтеграцияС1СДокументооборотом

	упо_Интеграция.ПриСозданииНаСервере(ЭтаФорма, Отказ, СтандартнаяОбработка);

	// Оповещения PM
	упо_ОповещенияВызовСервера.ДобавитьЭлементыПодписки(ЭтаФорма, Объект, Элементы.Страницы);
	// Конец Оповещения PM
	// {/PM}
КонецПроцедуры

&НаСервере
&После("ПередЗаписьюНаСервере")
Процедура упо_ПередЗаписьюНаСервере(Отказ, ТекущийОбъект, ПараметрыЗаписи)

	// {PM}
	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПередЗаписьюНаСервере(ЭтотОбъект, ТекущийОбъект, ПараметрыЗаписи);
	// Конец ИнтеграцияС1СДокументооборотом
	// {/PM}

КонецПроцедуры

&НаСервере
&После("ПослеЗаписиНаСервере")
Процедура упо_ПослеЗаписиНаСервере(ТекущийОбъект, ПараметрыЗаписи)

	// {PM}
	// Оповещения PM
	упо_ОповещенияВызовСервера.СохранитьПодписку(ЭтаФорма, ТекущийОбъект);
	// Конец Оповещения PM
	// {/PM}

КонецПроцедуры

&НаКлиенте
&Перед("ПослеЗаписи")
Процедура упо_ПослеЗаписи(ПараметрыЗаписи)

	Если ПараметрыЗаписи.Свойство("ДобавленПользовательИБ") Тогда

		// {PM}
		ОписаниеОповещения = Новый ОписаниеОповещения("упо_СоздатьСвязанныйРесурсПользователяОбработкаОтвета", ЭтотОбъект);
		ПоказатьВопрос(ОписаниеОповещения, НСтр("ru = 'Cоздать связанный ресурс?'"), РежимДиалогаВопрос.ДаНет);
		// {/PM}

	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Процедура Подключаемый_ВыполнитьКомандуИнтеграции(Команда)
	// {PM}
	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональностьКлиент.ВыполнитьПодключаемуюКомандуИнтеграции(Команда, ЭтотОбъект, Объект);
	// Конец ИнтеграцияС1СДокументооборотом
	// {/PM}
КонецПроцедуры

&НаКлиенте
Процедура Подключаемый_ОповещенияПодпискиПриИзменении(Элемент)
	// {PM}
	упо_СохранитьПодпискиНаСобытия();
	// {/PM}
КонецПроцедуры

&НаКлиенте
Процедура Подключаемый_упо_СоздатьСвязанныйРесурсПользователя(Команда)

	// {PM}
	СсылкаНаОбъект = Объект.Ссылка;

	Если НЕ ЗначениеЗаполнено(СсылкаНаОбъект) Тогда
		Возврат;
	КонецЕсли;

	ОповещениеОЗакрытии = Новый ОписаниеОповещения("упо_ОбновитьДинамическийСписокРесурсовПользователя", ЭтаФорма);

	ПараметрыЗаполнения = Новый Структура;
	ПараметрыЗаполнения.Вставить("упо_НовыйДиспетчерРесурса", СсылкаНаОбъект);

	ПараметрыФормы = Новый Структура("ЗначенияЗаполнения", ПараметрыЗаполнения);

	ОткрытьФорму("Документ.упо_РегистрацияДиспетчеровРесурсов.Форма.ФормаДокумента", ПараметрыФормы, 
		ЭтаФорма, , , , ОповещениеОЗакрытии, РежимОткрытияОкнаФормы.БлокироватьОкноВладельца);
	// {/PM}

КонецПроцедуры

&НаКлиенте
Процедура упо_ОбновитьДинамическийСписокРесурсовПользователя(Результат, ДополнительныеПараметры) Экспорт

	// {PM}
	ОбщегоНазначенияКлиентСервер.УстановитьПараметрДинамическогоСписка(ЭтаФорма.упо_РесурсыПользователя,
		"Пользователь", Объект.Ссылка);  

	Элементы.упо_РесурсыПользователя.Обновить();

	ОбщегоНазначенияКлиентСервер.УстановитьПараметрДинамическогоСписка(ЭтаФорма.упо_ИсторияНазначенияРесурсов,
		"Пользователь", Объект.Ссылка);    

	Элементы.упо_ИсторияНазначенияРесурсов.Обновить();
	// {/PM}

КонецПроцедуры

&НаКлиенте
Процедура упо_СоздатьСвязанныйРесурсПользователяОбработкаОтвета(РезультатВопроса, ДополнительныеПараметры) Экспорт

	// {PM}
	Если РезультатВопроса = КодВозвратаДиалога.Нет Тогда 
		Элементы.упо_СоздатьРесурсПользователя.Видимость = Истина;
		Возврат;	
	КонецЕсли; 

	ОповещениеОЗакрытии = Новый ОписаниеОповещения("упо_ОбновитьДинамическийСписокРесурсовПользователя", ЭтаФорма);

	ПараметрыЗаполнения = Новый Структура;
	ПараметрыЗаполнения.Вставить("упо_НовыйДиспетчерРесурса", Объект.Ссылка);

	ПараметрыФормы = Новый Структура;
	ПараметрыФормы.Вставить("ЗначенияЗаполнения", ПараметрыЗаполнения);	

	ОткрытьФорму("Справочник.упо_Ресурсы.Форма.ФормаЭлемента", ПараметрыФормы, 
		ЭтаФорма, , , , ОповещениеОЗакрытии, РежимОткрытияОкнаФормы.БлокироватьОкноВладельца);
	// {/PM}

КонецПроцедуры 

&НаСервере
Процедура упо_СохранитьПодпискиНаСобытия()
	// {PM}
	упо_ОповещенияВызовСервера.СохранитьПодписку(ЭтотОбъект, Объект.Ссылка);
	// {/PM}
КонецПроцедуры

&После("ПриЗаписи")
Процедура упо_ПриЗаписи(Отказ)
	// {PM}
	упо_Персонализация.ПриЗаписиПользователяИнформационнойБазы(ЭтотОбъект.Ссылка, ЭтоНовый);
	// {/PM}
КонецПроцедуры

&НаСервере
&После("ЗаполнитьДеревоРеквизитов")
Процедура упо_ЗаполнитьДеревоРеквизитов(ИмяМетаданных, ИмяРеквизитаОбъектаИС, ПредставлениеРеквизитаОбъектаДО,
		ЭтоТаблица, Таблица)

	Дерево = РеквизитФормыВЗначение("ДеревоРеквизитов");
	Объект = Метаданные.НайтиПоПолномуИмени(ИмяМетаданных);

	Если Объект = Неопределено Тогда
		Возврат;
	КонецЕсли;

	Если Не ЭтоТаблица Тогда

		Для Каждого Реквизит Из Объект.СтандартныеРеквизиты Цикл

			Если Реквизит.Имя = "Проведен" Или Реквизит.Имя = "Ссылка" Тогда
				Продолжить;
			КонецЕсли;

			Представление = Реквизит.Представление();

			НоваяСтрока = Дерево.Строки.Добавить();
			НоваяСтрока.Имя = Реквизит.Имя;
			НоваяСтрока.Путь = Реквизит.Имя;
			НоваяСтрока.Представление = Представление;
			НоваяСтрока.ПредставлениеПути = Представление;
			НоваяСтрока.Тип = Реквизит.Тип;

			Типы = Реквизит.Тип.Типы();
			Если Типы.Количество() > 1 Тогда
				Продолжить;
			КонецЕсли;

			ОбъектРеквизит = Метаданные.НайтиПоТипу(Типы[0]);
			Если ОбъектРеквизит = Неопределено Тогда
				Продолжить;
			КонецЕсли;
			НоваяСтрока.ИмяМетаданных = ОбъектРеквизит.ПолноеИмя();

			Если Метаданные.Справочники.Содержит(ОбъектРеквизит)
					Или Метаданные.Документы.Содержит(ОбъектРеквизит)
					Или Метаданные.БизнесПроцессы.Содержит(ОбъектРеквизит)
					Или Метаданные.Задачи.Содержит(ОбъектРеквизит)
					Или Метаданные.ПланыВидовХарактеристик.Содержит(ОбъектРеквизит)
					Или Метаданные.ПланыСчетов.Содержит(ОбъектРеквизит) Тогда

				НоваяСтрока.ЕстьРеквизиты = Истина;
				НоваяСтрока.Строки.Добавить();

			КонецЕсли;

		КонецЦикла;

		НоваяСтрока = Дерево.Строки.Добавить();
		НоваяСтрока.Имя = "Представление";
		НоваяСтрока.Путь = "Представление";
		НоваяСтрока.Представление = НСтр("ru = 'Представление'");
		НоваяСтрока.ПредставлениеПути = НСтр("ru = 'Представление'");
		НоваяСтрока.Тип = "Строка";

		Для Каждого Реквизит Из Объект.Реквизиты Цикл

			Если СтрНачинаетсяС(Реквизит.Имя, "Удалить") Тогда
				Продолжить;
			КонецЕсли;

			Представление = Реквизит.Представление();

			НоваяСтрока = Дерево.Строки.Добавить();
			НоваяСтрока.Имя = Реквизит.Имя;
			НоваяСтрока.Путь = Реквизит.Имя;
			НоваяСтрока.Представление = Представление;
			НоваяСтрока.ПредставлениеПути = Представление;
			НоваяСтрока.Тип = Реквизит.Тип;

			Типы = Реквизит.Тип.Типы();
			Если Типы.Количество() > 1 Тогда
				Продолжить;
			КонецЕсли;

			ОбъектРеквизит = Метаданные.НайтиПоТипу(Типы[0]);
			Если ОбъектРеквизит = Неопределено Тогда
				Продолжить;
			КонецЕсли;
			НоваяСтрока.ИмяМетаданных = ОбъектРеквизит.ПолноеИмя();

			Если Метаданные.Справочники.Содержит(ОбъектРеквизит)
					Или Метаданные.Документы.Содержит(ОбъектРеквизит)
					Или Метаданные.БизнесПроцессы.Содержит(ОбъектРеквизит)
					Или Метаданные.Задачи.Содержит(ОбъектРеквизит)
					Или Метаданные.ПланыВидовХарактеристик.Содержит(ОбъектРеквизит)
					Или Метаданные.ПланыСчетов.Содержит(ОбъектРеквизит) Тогда

				НоваяСтрока.ЕстьРеквизиты = Истина;
				НоваяСтрока.Строки.Добавить();

			КонецЕсли;

		КонецЦикла;

		Если Метаданные.ФункциональныеОпции.Найти("ИспользоватьДополнительныеРеквизитыИСведения") <> Неопределено
				И ПолучитьФункциональнуюОпцию("ИспользоватьДополнительныеРеквизитыИСведения") Тогда

			ИмяТипа = ИнтеграцияС1СДокументооборотБазоваяФункциональностьКлиентСервер.ИмяТипаИзПолногоИмени(ИмяМетаданных);
			ВладелецСвойств = Новый(Тип(ИмяТипа));

			Если УправлениеСвойствами.ИспользоватьДопРеквизиты(ВладелецСвойств) Тогда

				НаборДопРеквизитов = УправлениеСвойствами.СвойстваОбъекта(ВладелецСвойств, Истина, Ложь);
				СвойстваДопРеквизитов = ОбщегоНазначения.ЗначенияРеквизитовОбъектов(
					НаборДопРеквизитов,
					"Наименование, ТипЗначения");

				Для Каждого ДопРеквизит Из НаборДопРеквизитов Цикл
					СвойстваДопРеквизита = СвойстваДопРеквизитов[ДопРеквизит];

					НоваяСтрока = Дерево.Строки.Добавить();
					НоваяСтрока.Имя = СвойстваДопРеквизита.Наименование;
					НоваяСтрока.Путь = СвойстваДопРеквизита.Наименование;
					НоваяСтрока.Представление = СвойстваДопРеквизита.Наименование;
					НоваяСтрока.ПредставлениеПути = СвойстваДопРеквизита.Наименование;
					НоваяСтрока.Тип = СвойстваДопРеквизита.ТипЗначения;
					НоваяСтрока.ЭтоДополнительныйРеквизитИС = Истина;
					НоваяСтрока.ДополнительныйРеквизитИС = ДопРеквизит;
				КонецЦикла;

			КонецЕсли;

		КонецЕсли;

	КонецЕсли;

	Если ЭтоТаблица Или ЗначениеЗаполнено(Таблица) Тогда

		Для Каждого ТабличнаяЧасть Из Объект.ТабличныеЧасти Цикл

			СтрокиДерева = Дерево.Строки;

			Если СтрНачинаетсяС(ТабличнаяЧасть.Имя, "Удалить") Тогда
				Продолжить;
			КонецЕсли;

			Если ЭтоТаблица Тогда

				НоваяСтрока = СтрокиДерева.Добавить();
				НоваяСтрока.Имя = ТабличнаяЧасть.Имя;
				НоваяСтрока.Путь = ТабличнаяЧасть.Имя;
				НоваяСтрока.Представление = ?(ЗначениеЗаполнено(ТабличнаяЧасть.Синоним),
					ТабличнаяЧасть.Синоним,
					ТабличнаяЧасть.Имя);
				НоваяСтрока.ПредставлениеПути = НоваяСтрока.Представление;
				НоваяСтрока.Тип = НСтр("ru = 'Таблица'");
				НоваяСтрока.ЭтоТаблица = Истина;

			Иначе

				НоваяСтрока = СтрокиДерева.Добавить();
				НоваяСтрока.Имя = ТабличнаяЧасть.Имя;
				НоваяСтрока.Путь = ТабличнаяЧасть.Имя;
				НоваяСтрока.Представление = ?(ЗначениеЗаполнено(ТабличнаяЧасть.Синоним),
					ТабличнаяЧасть.Синоним,
					ТабличнаяЧасть.Имя);
				НоваяСтрока.ПредставлениеПути = НоваяСтрока.Представление;
				НоваяСтрока.Тип = НСтр("ru = 'Таблица'");
				НоваяСтрока.ЭтоТаблица = Истина;
				НоваяСтрока.Недоступно = Истина;
				НоваяСтрока.Выделено = (Таблица = ТабличнаяЧасть.Имя);
				НоваяСтрока.РеквизитыСчитаны = Истина;

				СтрокиДерева = НоваяСтрока.Строки;

				Для Каждого Реквизит Из ТабличнаяЧасть.Реквизиты Цикл

					Если СтрНачинаетсяС(Реквизит.Имя, "Удалить") Тогда
						Продолжить;
					КонецЕсли;

					Представление = Реквизит.Представление();

					НоваяСтрока = СтрокиДерева.Добавить();
					НоваяСтрока.Имя = Реквизит.Имя;
					НоваяСтрока.Путь = ТабличнаяЧасть.Имя + "." + Реквизит.Имя;
					НоваяСтрока.Представление = Представление;
					НоваяСтрока.ПредставлениеПути = Представление;
					НоваяСтрока.Тип = Реквизит.Тип;
					НоваяСтрока.Таблица = ТабличнаяЧасть.Имя;
					НоваяСтрока.Недоступно = (Таблица <> ТабличнаяЧасть.Имя);

				КонецЦикла;

			КонецЕсли;

		КонецЦикла;

	КонецЕсли;

	// {PM}
	упо_Интеграция.ЗаполнитьДеревоРеквизитов(Дерево, 
		Объект,
		ИмяРеквизитаОбъектаИС,
		ПредставлениеРеквизитаОбъектаДО,
		ЭтоТаблица,
		Таблица);
	// {/PM}
	Дерево.Строки.Сортировать("Представление");

	ЗначениеВРеквизитФормы(Дерево, "ДеревоРеквизитов");

	// Найдем таблицу
	Если ЗначениеЗаполнено(Таблица) Тогда
		Для Каждого ЭлементДерева Из ДеревоРеквизитов.ПолучитьЭлементы() Цикл
			Если ЭлементДерева.ЭтоТаблица
				И ЭлементДерева.Имя = Таблица Тогда
				Элементы.ДеревоРеквизитов.ТекущаяСтрока = ЭлементДерева.ПолучитьИдентификатор();
			КонецЕсли;
		КонецЦикла;
	КонецЕсли;

	// Найдем ранее выбранный элемент.
	Если ЗначениеЗаполнено(ИмяРеквизитаОбъектаИС) Тогда
		Для Каждого ЭлементДерева Из ДеревоРеквизитов.ПолучитьЭлементы() Цикл
			Если ЭлементДерева.Имя = ИмяРеквизитаОбъектаИС
				И ЭлементДерева.Таблица = Таблица Тогда
				Элементы.ДеревоРеквизитов.ТекущаяСтрока = ЭлементДерева.ПолучитьИдентификатор();
				Возврат;
			КонецЕсли;
			Если ЭлементДерева.ЭтоТаблица Тогда
				Для Каждого ПодчиненныйЭлемент Из ЭлементДерева.ПолучитьЭлементы() Цикл
					Если СтрШаблон("%1.%2", ПодчиненныйЭлемент.Таблица, ПодчиненныйЭлемент.Имя) = ИмяРеквизитаОбъектаИС Тогда
						Элементы.ДеревоРеквизитов.ТекущаяСтрока = ПодчиненныйЭлемент.ПолучитьИдентификатор();
						Возврат;
					КонецЕсли;
				КонецЦикла;
			КонецЕсли;
		КонецЦикла;
	КонецЕсли;

	// Найдем подходящий по представлению.
	Для Каждого ЭлементДерева Из ДеревоРеквизитов.ПолучитьЭлементы() Цикл
		Если ЭлементДерева.Представление = ПредставлениеРеквизитаОбъектаДО
				И ЭлементДерева.Таблица = Таблица Тогда
			Элементы.ДеревоРеквизитов.ТекущаяСтрока = ЭлементДерева.ПолучитьИдентификатор();
			Возврат;
		КонецЕсли;
		Если ЭлементДерева.ЭтоТаблица Тогда
			Для Каждого ПодчиненныйЭлемент Из ЭлементДерева.ПолучитьЭлементы() Цикл
				Если ПодчиненныйЭлемент.Представление = ПредставлениеРеквизитаОбъектаДО
						И ПодчиненныйЭлемент.Таблица = Таблица Тогда
					Элементы.ДеревоРеквизитов.ТекущаяСтрока = ПодчиненныйЭлемент.ПолучитьИдентификатор();
					Возврат;
				КонецЕсли;
			КонецЦикла;
		КонецЕсли;
	КонецЦикла;

КонецПроцедуры

&ИзменениеИКонтроль("ЗаполнитьФормуОбъектаДОПоПравилу")
Процедура упо_ЗаполнитьФормуОбъектаДОПоПравилу(Источник, Форма, Правило)

	// Правило, переданное в виде ссылки, нуждается в выборке запросом.
	Если ТипЗнч(Правило) = Тип("СправочникСсылка.ПравилаИнтеграцииС1СДокументооборотом") Тогда
		ДанныеПравила = ДанныеПравилаДляВыгрузки(Правило);
	Иначе // Передана сразу структура данных.
		ДанныеПравила = Правило;
	КонецЕсли;

	ПараметрыЗаполнения = Новый Структура("documentType", ВидДокументаИзПравила(ДанныеПравила));

	СоответствиеСвойствXDTOиРеквизитов = СоответствиеСвойствXDTOиРеквизитовФормыОбъектаДО(Форма.Тип);
	ИсточникОбъект = Источник.ПолучитьОбъект();
	МетаданныеИсточника = Источник.Метаданные();
	НастройкиВида = Неопределено;

	РеквизитыОбъектаДО = РеквизитыОбъектаДО(ДанныеПравила.ТипОбъектаДО, ПараметрыЗаполнения, НастройкиВида);

	ЯвляетсяЗаявкойНаОплату = Ложь;
	Если НастройкиВида <> Неопределено
		И ИнтеграцияС1СДокументооборотБазоваяФункциональность.СвойствоСуществует(НастройкиВида, "isAPaymentRequest")
		И НастройкиВида.isAPaymentRequest = Истина Тогда
		ЯвляетсяЗаявкойНаОплату = Истина;
	КонецЕсли;
	Если ЯвляетсяЗаявкойНаОплату Тогда
		СоответствиеСвойствXDTOиРеквизитов.Вставить("recipient", "Получатель");
	КонецЕсли;

	Для Каждого РеквизитОбъектаДО Из РеквизитыОбъектаДО Цикл

		ПараметрыОтбора = Новый Структура;
		ПараметрыОтбора.Вставить("ЭтоДополнительныйРеквизитДО", РеквизитОбъектаДО.ДопРеквизит);
		Если РеквизитОбъектаДО.ДопРеквизит Тогда
			ПараметрыОтбора.Вставить("ДополнительныйРеквизитДОID", РеквизитОбъектаДО.ДопРеквизитID);
			ПараметрыОтбора.Вставить("ДополнительныйРеквизитДОТип", РеквизитОбъектаДО.ДопРеквизитТип);
			ПараметрыОтбора.Вставить("ЭтоТаблица", Ложь);
			ПараметрыОтбора.Вставить("Таблица", "");
		Иначе
			ПараметрыОтбора.Вставить("ИмяРеквизитаОбъектаДО", РеквизитОбъектаДО.Имя);
			ПараметрыОтбора.Вставить("ЭтоТаблица", РеквизитОбъектаДО.ЭтоТаблица);
			ПараметрыОтбора.Вставить("Таблица", РеквизитОбъектаДО.Таблица);
		КонецЕсли;

		НайденныеПравилаРеквизитов = ДанныеПравила.ПравилаЗаполненияРеквизитовДО.НайтиСтроки(ПараметрыОтбора);
		Если НайденныеПравилаРеквизитов.Количество() = 0 Тогда
			Продолжить;
		КонецЕсли;
		ПравилоРеквизита = НайденныеПравилаРеквизитов[0]; // СправочникТабличнаяЧастьСтрока.ПравилаИнтеграцииС1СДокументооборотом.ПравилаЗаполненияРеквизитовДО

		Если Не РеквизитОбъектаДО.ДопРеквизит Тогда

			Если ЗначениеЗаполнено(РеквизитОбъектаДО.Таблица) Тогда

				РазделеннаяСтрока = СтрРазделить(РеквизитОбъектаДО.Таблица, ".", Ложь);
				СвойствоВладелец = СоответствиеСвойствXDTOиРеквизитов[РазделеннаяСтрока[0]];
				ОписаниеТаблицы = СвойствоВладелец[РазделеннаяСтрока[1]];
				ИмяТаблицы = ОписаниеТаблицы[0];
				ИмяРеквизита = ОписаниеТаблицы[1][РеквизитОбъектаДО.Имя];

			ИначеЕсли РеквизитОбъектаДО.ЭтоТаблица Тогда

				РазделеннаяСтрока = СтрРазделить(РеквизитОбъектаДО.Имя, ".", Ложь);
				СвойствоВладелец = СоответствиеСвойствXDTOиРеквизитов[РазделеннаяСтрока[0]];
				ОписаниеТаблицы = СвойствоВладелец[РазделеннаяСтрока[1]];
				ИмяТаблицы = ОписаниеТаблицы[0];
				ИмяРеквизита = "";

			Иначе

				ИмяТаблицы = "";
				ИмяРеквизита = СоответствиеСвойствXDTOиРеквизитов[РеквизитОбъектаДО.Имя];

			КонецЕсли;

			Если РеквизитОбъектаДО.ЭтоТаблица Тогда

				Форма[ИмяТаблицы].Очистить();

				Если ПравилоРеквизита.Вариант = ВариантРеквизит() Тогда // Наполним пустыми строками.

					ТабличнаяЧасть = ИсточникОбъект[ПравилоРеквизита.ИмяРеквизитаОбъектаИС];
					Для Счетчик = 1 По ТабличнаяЧасть.Количество() Цикл
						Форма[ИмяТаблицы].Добавить();
					КонецЦикла;

				ИначеЕсли ПравилоРеквизита.Вариант = ВариантРеквизитТаблицы() Тогда // Добавим единственную строку.

					Форма[ИмяТаблицы].Добавить();

				ИначеЕсли ПравилоРеквизита.Вариант = ВариантВыражение() Тогда // Загрузим из результата-таблицы.

					Параметры = Новый Структура;
					Параметры.Вставить("Источник", ИсточникОбъект);
					Параметры.Вставить("Результат", Неопределено);

					ИнтеграцияС1СДокументооборотБазоваяФункциональность.ВыполнитьВБезопасномРежиме(
					ПравилоРеквизита.ВычисляемоеВыражение,
					Параметры);

					СтандартнаяОбработка = Истина;
					ИнтеграцияС1СДокументооборотБазоваяФункциональностьПереопределяемый.ПриЗаполненииСвойстваОбъектаXDTOПоЗначению(
					Параметры.Результат,
					Форма,
					ДанныеПравила.ТипОбъектаДО,
					ИмяТаблицы,
					Неопределено,
					СтандартнаяОбработка);

					Если Не СтандартнаяОбработка Тогда
						Продолжить;
					КонецЕсли;

					Если ТипЗнч(Параметры.Результат) = Тип("ТаблицаЗначений") Тогда
						КолонкиТаблицы = Параметры.Результат.Колонки; // КоллекцияКолонокТаблицыЗначений

						Для Каждого СтрокаРезультата Из Параметры.Результат Цикл
							СтрокаФормы = Форма[ИмяТаблицы].Добавить();
							Для Каждого Колонка Из КолонкиТаблицы Цикл
								Если Не СтрокаФормы.Свойство(Колонка.Имя) Тогда
									Продолжить;
								КонецЕсли;
								Значение = СтрокаРезультата[Колонка.Имя];
								СтрокаФормы[Колонка.Имя] = Значение;
								Если Не СтрокаФормы.Свойство(Колонка.Имя + "ID") Тогда
									Продолжить;
								КонецЕсли;
								Если ИнтеграцияС1СДокументооборотБазоваяФункциональность.ЕстьУникальныйИдентификатор(Значение) Тогда
									СтрокаФормы[Колонка.Имя + "ID"] = Строка(Значение.УникальныйИдентификатор());
									СтрокаФормы[Колонка.Имя + "Тип"] = Значение.Метаданные().ПолноеИмя();
								ИначеЕсли ЭтоПеречисление(Значение) Тогда
									Если ОбщегоНазначения.СсылкаСуществует(Значение) Тогда
										СтрокаФормы[Колонка.Имя + "ID"] = ОбщегоНазначения.ИмяЗначенияПеречисления(Значение);
									КонецЕсли;
									СтрокаФормы[Колонка.Имя + "Тип"] = Значение.Метаданные().ПолноеИмя();
								Иначе
									СтрокаФормы[Колонка.Имя + "ID"] = Строка(Значение);
									СтрокаФормы[Колонка.Имя + "Тип"] = "Строка";
								КонецЕсли;
							КонецЦикла;
						КонецЦикла;
					КонецЕсли;

				Иначе // Значениями, указанными для реквизитов: добавим единственную строку.

					Форма[ИмяТаблицы].Добавить();

				КонецЕсли;

				Продолжить;

			КонецЕсли; // Это таблица.

			ТипРеквизитаДО = РеквизитОбъектаДО.Тип[0].Значение;

			Если ПравилоРеквизита.Вариант = ВариантРеквизит() Тогда

				ИмяРеквизитаОбъектаИС = ПравилоРеквизита.ИмяРеквизитаОбъектаИС;

				Если ЗначениеЗаполнено(ПравилоРеквизита.Таблица) Тогда // Реквизит табличной части.

					РазделеннаяСтрока = СтрРазделить(ИмяРеквизитаОбъектаИС, ".");
					Если РазделеннаяСтрока.Количество() = 2 Тогда
						ТабличнаяЧасть = ИсточникОбъект[РазделеннаяСтрока[0]];
						Значения = ТабличнаяЧасть.ВыгрузитьКолонку(РазделеннаяСтрока[1]);
					Иначе
						Значения = Новый Массив;
						Значения.Добавить(ИсточникОбъект[РазделеннаяСтрока[0]]);
					КонецЕсли;

				Иначе // Обычный или дополнительный реквизит.

					Значения = Новый Массив;

					Если ИмяРеквизитаОбъектаИС = "Представление" Тогда

						Значения.Добавить(Строка(ИсточникОбъект));

					ИначеЕсли Найти(ИмяРеквизитаОбъектаИС, ".") > 0
						И Не ПравилоРеквизита.ЭтоДополнительныйРеквизитИС Тогда

						#Удаление
						ЗначениеРеквизита = ОбщегоНазначения.ЗначениеРеквизитаОбъекта(Источник, ИмяРеквизитаОбъектаИС);
						#КонецУдаления
						#Вставка
						// {PM}
						ЗначениеРеквизита = упо_Интеграция.
							ПолучитьЗначениеРеквизитаЭлементаПлана(ИсточникОбъект, ИмяРеквизитаОбъектаИС);
						Если ЗначениеРеквизита = Неопределено Тогда
							ЗначениеРеквизита = ОбщегоНазначения.ЗначениеРеквизитаОбъекта(Источник, ИмяРеквизитаОбъектаИС);
						КонецЕсли;
						// {/PM}
						#КонецВставки
						Значения.Добавить(ЗначениеРеквизита);

					Иначе

						Если ПравилоРеквизита.ЭтоДополнительныйРеквизитИС Тогда

							ТекстЗапроса =
							"ВЫБРАТЬ РАЗРЕШЕННЫЕ ПЕРВЫЕ 1
							|	ДополнительныеРеквизиты.Значение КАК ЗначениеРеквизита
							|ИЗ
							|	&ДополнительныеРеквизиты КАК ДополнительныеРеквизиты
							|ГДЕ
							|	ДополнительныеРеквизиты.Ссылка = &Источник
							|	И ДополнительныеРеквизиты.Свойство = &Свойство";
							ТекстЗапроса = СтрЗаменить(
							ТекстЗапроса,
							"&ДополнительныеРеквизиты",
							МетаданныеИсточника.ПолноеИмя() +"." + "ДополнительныеРеквизиты");

							Запрос = Новый Запрос(ТекстЗапроса);
							Запрос.УстановитьПараметр("Источник", Источник);
							Запрос.УстановитьПараметр("Свойство", ПравилоРеквизита.ДополнительныйРеквизитИС);
							Значения = Запрос.Выполнить().Выгрузить().ВыгрузитьКолонку("ЗначениеРеквизита");

						Иначе // Обычный реквизит.

							Попытка

								#Удаление
								Значения.Добавить(ИсточникОбъект[ИмяРеквизитаОбъектаИС]);
								#КонецУдаления
								#Вставка
								// {PM}
								ЗначениеРеквизита = упо_Интеграция.
									ПолучитьЗначениеРеквизитаЭлементаПлана(ИсточникОбъект, ИмяРеквизитаОбъектаИС);
								Если ЗначениеРеквизита = Неопределено Тогда
									Значения.Добавить(ИсточникОбъект[ИмяРеквизитаОбъектаИС]);
								Иначе
									Значения.Добавить(ЗначениеРеквизита);
								КонецЕсли;
								// {/PM}
								#КонецВставки

							Исключение // В случае отсутствия реквизита выдадим понятное сообщение об ошибке.

								Инфо = ИнформацияОбОшибке();
								Если МетаданныеИсточника.Реквизиты.Найти(ИмяРеквизитаОбъектаИС) = Неопределено
									И ПравилоРеквизита.ИмяРеквизитаОбъектаИС <> "Представление" Тогда
									Найден = Ложь;
									Для Каждого СтандартныйРеквизит Из МетаданныеИсточника.СтандартныеРеквизиты Цикл
										Если СтандартныйРеквизит.Имя = ПравилоРеквизита.ИмяРеквизитаОбъектаИС Тогда
