			Если МассивСтрокДопРеквизитов.Количество() > 0 Тогда
				Элемент = МассивСтрокДопРеквизитов[0];
			Иначе
				// Дополнительный реквизит принадлежит конкретному виду документа.
				Элемент = Форма.Свойства.Добавить();
