#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаКлиенте
Функция ЭтоВерсииПланов(ПараметрКоманды)

	ТипПланы = Тип("СправочникСсылка.упо_Планы");

	Если ТипЗнч(ПараметрКоманды) = ТипПланы Тогда
		Возврат Истина;
	ИначеЕсли ТипЗнч(ПараметрКоманды) = Тип("Массив") И ТипЗнч(ПараметрКоманды[0]) = ТипПланы Тогда
		Возврат Истина;
	Иначе
		Возврат Ложь;
	КонецЕсли;

КонецФункции

#КонецОбласти

#Область ОбработчикиСобытий

&НаКлиенте
Процедура ОбработкаКоманды(ПараметрКоманды, ПараметрыВыполненияКоманды)

	ИмяФормы = "Справочник.упо_ВерсииПланов.Форма.ФормаЭлементаСтруктуры";
	Если ТипЗнч(ПараметрыВыполненияКоманды.Источник) <> Тип("ФормаКлиентскогоПриложения")
			ИЛИ ПараметрыВыполненияКоманды.Источник.ИмяФормы <> ИмяФормы Тогда

		Возврат;
	КонецЕсли;

	Источник = ПараметрыВыполненияКоманды.Источник;

	Если НЕ ЗначениеЗаполнено(Источник.ОбъектЕдиногоЭлементаПлана) Тогда
		Если СоздатьОбъектСправочникаНаФормеИсточнике(Источник) Тогда
			ПараметрыОповещения = Новый Структура;
			ПараметрыОповещения.Вставить("ЭлементУИД", Источник.ЭлементУИД);
			Оповестить("СозданОбъектЕдиногоЭлемента", ПараметрыОповещения);
		Иначе
			Возврат;
		КонецЕсли;
	КонецЕсли;

	Настройки = ИнтеграцияС1СДокументооборотБазоваяФункциональностьВызовСервера.ИспользоватьИнтеграцию();
	Если Настройки.ИспользоватьИнтеграциюДО2 Тогда
		ИмяФормы = "Обработка.ИнтеграцияС1СДокументооборот.Форма.Документооборот";
	ИначеЕсли Настройки.ИспользоватьИнтеграциюДО3 Тогда
		ИмяФормы = "Обработка.ИнтеграцияС1СДокументооборот3.Форма.Документооборот";
	КонецЕсли;

	ПараметрыФормы = Новый Структура("ВнешнийОбъект", Источник.ОбъектЕдиногоЭлементаПлана);
	ОткрытьФорму(
		ИмяФормы,
		ПараметрыФормы,
		ПараметрыВыполненияКоманды.Источник,
		ПараметрыВыполненияКоманды.Уникальность,
		ПараметрыВыполненияКоманды.Окно);

КонецПроцедуры

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаКлиенте
Функция СоздатьОбъектСправочникаНаФормеИсточнике(Форма)

	ЕдиныйЭлементУИД = Форма.ЕдиныйЭлементУИД;

	Если НЕ ЗначениеЗаполнено(ЕдиныйЭлементУИД) Тогда

		Текст = НСтр("ru ='Не заполнен идентификатор единого элемента плана'");
		ОбщегоНазначенияКлиент.СообщитьПользователю(Текст);
		Возврат Ложь;
	КонецЕсли;

	РезультатСоздания = упо_ЕдиныеЭлементыПланаВызовСервера.СоздатьЭлементСправочникаОбъектыЕдиныхЭСП(ЕдиныйЭлементУИД);
	Если НЕ РезультатСоздания.Успешно Тогда
		ОбщегоНазначенияКлиент.СообщитьПользователю(РезультатСоздания.ТекстОшибки);
		Возврат Ложь;
	КонецЕсли;

	Форма.ОбъектЕдиногоЭлементаПлана = РезультатСоздания.Ссылка;

	Возврат Истина;
КонецФункции

#КонецОбласти

#Область ОбработчикиСобытий

&НаКлиенте
Процедура ОбработкаКоманды(ПараметрКоманды, ПараметрыВыполненияКоманды)

	ИмяФормы = "Справочник.упо_ВерсииПланов.Форма.ФормаЭлементаСтруктуры";
	Если ТипЗнч(ПараметрыВыполненияКоманды.Источник) <> Тип("ФормаКлиентскогоПриложения")
			ИЛИ ПараметрыВыполненияКоманды.Источник.ИмяФормы <> ИмяФормы Тогда

		Возврат;
	КонецЕсли;

	Источник = ПараметрыВыполненияКоманды.Источник;

	Если НЕ ЗначениеЗаполнено(Источник.ОбъектЕдиногоЭлементаПлана) Тогда
		Если СоздатьОбъектСправочникаНаФормеИсточнике(Источник) Тогда
			ПараметрыОповещения = Новый Структура;
			ПараметрыОповещения.Вставить("ЭлементУИД", Источник.ЭлементУИД);
			Оповестить("СозданОбъектЕдиногоЭлемента", ПараметрыОповещения);
		Иначе
			Возврат;
		КонецЕсли;
	КонецЕсли;

	ИнтеграцияС1СДокументооборот3Клиент.ОбработкаКомандыНачатьОбработку(Источник.ОбъектЕдиногоЭлементаПлана, ПараметрыВыполненияКоманды);

КонецПроцедуры

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаКлиенте
Функция СоздатьОбъектСправочникаНаФормеИсточнике(Форма)

	ЕдиныйЭлементУИД = Форма.ЕдиныйЭлементУИД;

	Если НЕ ЗначениеЗаполнено(ЕдиныйЭлементУИД) Тогда

		Текст = НСтр("ru ='Не заполнен идентификатор единого элемента плана'");
		ОбщегоНазначенияКлиент.СообщитьПользователю(Текст);
