	Параметры.Свойство("ВерсияПлана", ВерсияПлана);

	МассивСценариев = упо_СоставСценариев.ПолучитьМассивСценариевВерсии(ВерсияПлана);
	СписокСценариев.ЗагрузитьЗначения(МассивСценариев);

	ОграничитьДоступностьЭлементовФормы();

КонецПроцедуры

&НаКлиенте
Процедура КомандаЗаписатьИЗакрыть(Команда)
	Если Модифицированность Тогда
		ЗаписатьСоставСценариев();
	КонецЕсли;

	Закрыть();

КонецПроцедуры

&НаСервере
Процедура ЗаписатьСоставСценариев()

	упо_СоставСценариев.ЗаписатьСписокСценариевВерсии(ВерсияПлана, СписокСценариев);

КонецПроцедуры

#Область ОбработчикиСобытийЭлементовТаблицыФормыСписокСценариев

&НаКлиенте
Процедура СписокСценариевОбработкаВыбора(Элемент, ВыбранноеЗначение, СтандартнаяОбработка)

	СтандартнаяОбработка = Ложь;

	Для Каждого Сценарий Из ВыбранноеЗначение Цикл   

		Если СписокСценариев.НайтиПоЗначению(Сценарий) <> Неопределено Тогда
			Продолжить;
		КонецЕсли;

		Отказ = Ложь;
		ПроверитьДоступностьВключенияИсключенияСценария(Сценарий, Отказ);
		Если Отказ Тогда
			Продолжить;		
		КонецЕсли;

		СписокСценариев.Добавить(Сценарий);
		Модифицированность = Истина;
	КонецЦикла;
КонецПроцедуры

&НаКлиенте
Процедура СписокСценариевПередНачаломИзменения(Элемент, Отказ)

	ТекущиеДанные = Элементы.СписокСценариев.ТекущиеДанные;

	ПроверитьДоступностьВключенияИсключенияСценария(ТекущиеДанные.Значение, Отказ);

КонецПроцедуры

&НаКлиенте
Процедура СписокСценариевПередУдалением(Элемент, Отказ)

	ТекущиеДанные = Элементы.СписокСценариев.ТекущиеДанные;

	ПроверитьДоступностьВключенияИсключенияСценария(ТекущиеДанные.Значение, Отказ);

КонецПроцедуры

&НаКлиенте
Процедура СписокСценариевЗначениеПриИзменении(Элемент)

	ТекущиеДанные = Элементы.СписокСценариев.ТекущиеДанные;

	Отказ = Ложь;
	ПроверитьДоступностьВключенияИсключенияСценария(ТекущиеДанные.Значение, Отказ);
	Если Отказ Тогда
		ТекущиеДанные.Значение = Неопределено;
		СписокСценариев.Удалить(СписокСценариев.НайтиПоЗначению(ТекущиеДанные.Значение));	
	КонецЕсли;

КонецПроцедуры

#КонецОбласти

&НаКлиенте
Функция ПроверитьДоступностьВключенияИсключенияСценария(Сценарий, Отказ = Ложь)

	ИзменениеСоставаСценариевВерсий = ПараметрыОграниченияДоступа.ИзменениеСоставаСценариевВерсий;
	ВсеВерсииРазрешены = ИзменениеСоставаСценариевВерсий.ВсеВерсииРазрешены;
	Исключения = ИзменениеСоставаСценариевВерсий.Исключения;

	СвязанСНедоступнымСценарием = Ложь;
	Если ВсеВерсииРазрешены Тогда // Все разрешены, кроме...

		Если Исключения.Найти(Сценарий) <> Неопределено Тогда
			СвязанСНедоступнымСценарием	 = Истина;
		КонецЕсли;		

	Иначе // Все запрещены, кроме

		Если Исключения.Найти(Сценарий) = Неопределено Тогда
			СвязанСНедоступнымСценарием	 = Истина;
		КонецЕсли;		

	КонецЕсли;

	Если СвязанСНедоступнымСценарием Тогда
		Текст = НСтр("ru = 'Нет прав на операции со сценарием ""%1""'");
		Текст = СтрШаблон(Текст, Сценарий);
		ОбщегоНазначенияКлиент.СообщитьПользователю(Текст,,,, Отказ);
	КонецЕсли;

КонецФункции

&НаСервере
Процедура ОграничитьДоступностьЭлементовФормы()

	ВладельцыПолномочий = упо_Полномочия.НоваяСтруктураВладельцыПолномочий();
	ВладельцыПолномочий.ВерсияПлана = ВерсияПлана;
	ВладельцыПолномочий.ЦелевойВладелец = ВерсияПлана;
	ТекущиеПолномочияПользователя = упо_Полномочия.ТекущиеПолномочияПользователя(ВладельцыПолномочий);

	ПараметрыОграниченияДоступа = ТекущиеПолномочияПользователя.РасширенныеНастройкиПоОбластямДействия;

КонецПроцедуры

#Область ОбработчикиСобытийФормы

&НаСервере
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	ИнициализироватьПараметрыОткрытияФормы();
	ИнициализироватьНастройкиЭлементовФормы();

КонецПроцедуры

#КонецОбласти

#Область ОбработчикиСобытийЭлементовШапкиФормы

&НаКлиенте
Процедура СоздатьНовыйПланПриИзменении(Элемент)

	УстановитьНастройкиЭлементовФормыСоздатьНовыйПлан(ЭтотОбъект);

КонецПроцедуры

#КонецОбласти

