&НаКлиенте
Процедура КомандаСкопировать(Команда)

	НастройкиКопированияВерсии = НастройкиКопированияВерсий();
	Закрыть(НастройкиКопированияВерсии);

КонецПроцедуры

&НаКлиенте
Процедура КомандаНастройкиУстановитьПометку(Команда)
	УстановитьЗначениеВКолонкеНастроек(Истина);
КонецПроцедуры

&НаКлиенте
Процедура КомандаНастройкиСнятьПометку(Команда)
	УстановитьЗначениеВКолонкеНастроек(Ложь);
КонецПроцедуры

&НаКлиенте
Процедура КомандаПодборВерсииПлана(Команда)

	ОткрытьФормуПодбораВерсии();

КонецПроцедуры

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаСервере
Процедура ИнициализироватьПараметрыОткрытияФормы()

	ДанныеОтбора = Неопределено;
	Если Параметры.Свойство("ДанныеОтбора", ДанныеОтбора) Тогда
		Если ДанныеОтбора.Свойство("Владелец") И ЗначениеЗаполнено(ДанныеОтбора.Владелец) Тогда
			Если ТипЗнч(ДанныеОтбора.Владелец) = Тип("СписокЗначений") Тогда
				Владелец = ДанныеОтбора.Владелец;
			Иначе
				Владелец.ЗагрузитьЗначения(ДанныеОтбора.Владелец);
			КонецЕсли;
		КонецЕсли;
	КонецЕсли;

	ДанныеВыбора = Неопределено;
	Параметры.Свойство("ДанныеВыбора", ДанныеВыбора);
	Если Не ЗначениеЗаполнено(ДанныеВыбора) Тогда
		ВызватьИсключение(НСтр("ru = 'Не выбраны данные копирования'"));
	КонецЕсли;

	ВерсияВШапке = ДанныеВыбора.Количество() = 1;

	Если ВерсияВШапке Тогда

		ВерсияПланаИсточник = ДанныеВыбора[0];
		НаименованиеВерсии = КопияВНаименовании(ВерсияПланаИсточник);
		План = упо_ВерсииПланов.ПланВерсииПлана(ВерсияПланаИсточник);
		НаименованиеПлана = КопияВНаименовании(План);

	Иначе
		НастройкаЗаполненияПоУмолчанию = НастройкаЗаполненияПоУмолчанию();
		ЗаполнитьОбъектыКопированияВНастройкахКопирования(ДанныеВыбора, НастройкаЗаполненияПоУмолчанию);
	КонецЕсли;

КонецПроцедуры

&НаСервере
Процедура ЗаполнитьОбъектыКопированияВНастройкахКопирования(ОбъектыКопирования, НастройкаЗаполненияПоУмолчанию)

	ОбработатьСуществующиеВыбранныеВерсии(ОбъектыКопирования);
	ДобавитьНовыеВыбранныеВерсии(ОбъектыКопирования, НастройкаЗаполненияПоУмолчанию);

КонецПроцедуры

&НаСервере
Процедура ДобавитьНовыеВыбранныеВерсии(ОбъектыКопирования, НастройкаЗаполненияПоУмолчанию)

	Для Каждого ОбъектКопирования Из ОбъектыКопирования Цикл
		НоваяНастройка = НастройкиКопирования.Добавить();
		НоваяНастройка.ВерсияПланаИсточник = ОбъектКопирования;
		ЗаполнитьСвязанныеДанныеНастройкиКопирования(НоваяНастройка);
	КонецЦикла;
	ЗаполнитьНастройкиПоУмолчанию(НастройкаЗаполненияПоУмолчанию);

КонецПроцедуры

&НаСервере
Процедура ОбработатьСуществующиеВыбранныеВерсии(ОбъектыКопирования)

	Сч = НастройкиКопирования.Количество() - 1;
	Пока Сч >= 0 Цикл
		СтрокаКоллекции = НастройкиКопирования[Сч];
		Индекс = ОбъектыКопирования.Найти(СтрокаКоллекции.ВерсияПланаИсточник);
		Если Индекс = Неопределено Тогда
			НастройкиКопирования.Удалить(СтрокаКоллекции);
		Иначе
			ОбъектыКопирования.Удалить(Индекс);
		КонецЕсли;
		Сч = Сч - 1;
	КонецЦикла;

КонецПроцедуры

&НаСервере
Функция НастройкаЗаполненияПоУмолчанию()

	ЗначенияСвойствПоУмолчанию = Новый Структура;
	ЗначенияСвойствПоУмолчанию.Вставить("Пометка", Истина);
	ЗначенияСвойствПоУмолчанию.Вставить("СохранятьСвязьСИсточником", Ложь);
	ЗначенияСвойствПоУмолчанию.Вставить("СоздатьНовыйПлан", Ложь);

	Возврат ЗначенияСвойствПоУмолчанию;

КонецФункции

&НаСервере
Процедура ЗаполнитьСвязанныеДанныеНастройкиКопирования(НастройкаКопирования)

	Если Не ЗначениеЗаполнено(НастройкаКопирования.ВерсияПланаИсточник) Тогда
		Возврат;
	КонецЕсли;

	НастройкаКопирования.ПланИсточник = упо_ВерсииПланов.ПланВерсииПлана(НастройкаКопирования.ВерсияПланаИсточник);
	НастройкаКопирования.ОбъектПланаИсточник = 
		упо_ПланыОбъектовВызовСервера.ПолучитьСсылкуНаОбъектПлана(НастройкаКопирования.ПланИсточник);

КонецПроцедуры

&НаСервере
Процедура ЗаполнитьНастройкиПоУмолчанию(ЗначенияСвойствПоУмолчанию)

	Для Каждого НастройкаКопирования Из НастройкиКопирования Цикл
		ЗаполнитьЗначенияСвойств(НастройкаКопирования, ЗначенияСвойствПоУмолчанию);
		НастройкаКопирования.НаименованиеВерсии = КопияВНаименовании(НастройкаКопирования.ВерсияПланаИсточник);
		НастройкаКопирования.НаименованиеПлана = КопияВНаименовании(НастройкаКопирования.ПланИсточник);
	КонецЦикла;

КонецПроцедуры

&НаСервереБезКонтекста
Функция СтрокаНастройкиПоСчетчику(НастройкиКопирования, НастройкаКопирования, Счетчик)

	Если Счетчик = 1 Тогда
		СтрокаНастройки = НастройкаКопирования;
	Иначе
		СтрокаНастройки = НастройкиКопирования.Добавить();
	КонецЕсли;
	Счетчик = Счетчик + 1;

	Возврат СтрокаНастройки;

КонецФункции

&НаСервере
Процедура ИнициализироватьНастройкиЭлементовФормы()

	СтандартныеПодсистемыСервер.СброситьРазмерыИПоложениеОкна(ЭтотОбъект);

	Если ВерсияВШапке Тогда
		Элементы.СтраницыРасшифровка.ТекущаяСтраница = Элементы.СтраницаРасшифровкаСтрокой;
		ЭтотОбъект.Ширина = 90;
	Иначе
		Заголовок = НСтр("ru = 'Настройки копирования версий плана'");
		Элементы.СтраницыРасшифровка.ТекущаяСтраница = Элементы.СтраницаРасшифровкаТаблицей;
		Элементы.НастройкиКопирования.Ширина = 100;
		Элементы.НастройкиКопирования.Высота = 0;
	КонецЕсли;

	СохранитьНазначенияОтветственных = Истина;

	УстановитьНастройкиЭлементовФормыСоздатьНовыйПлан(ЭтотОбъект);

КонецПроцедуры

&НаКлиентеНаСервереБезКонтекста
Функция КопияВНаименовании(Знач Наименование)

	Если Не ТипЗнч(Наименование) = Тип("Строка") Тогда
		Наименование = Строка(Наименование);
	КонецЕсли;

	КопияВНаим = СтрШаблон("%1 (копия) %2", Наименование, ТекущаяДата());

	Возврат КопияВНаим;

КонецФункции

&НаКлиенте
Функция НастройкаКопированияВерсии(ИсточникДанных)

	ЗначенияЗаполненияНовогоПлана = Новый Структура();
	ЗначенияЗаполненияНовогоПлана.Вставить("Наименование", ИсточникДанных.НаименованиеПлана);
	ЗначенияЗаполненияНовогоПлана.Вставить("ЭтоШаблон", ИсточникДанных.ЭтоШаблон);

	НастройкаКопированияВерсии = Новый Структура();
	НастройкаКопированияВерсии.Вставить("НаименованиеВерсииПлана", ИсточникДанных.НаименованиеВерсии);
	НастройкаКопированияВерсии.Вставить("СохранятьСвязьСИсточником", ИсточникДанных.СохранятьСвязьСИсточником);
	НастройкаКопированияВерсии.Вставить("СохранитьНазначенияОтветственных",
		ИсточникДанных.СохранитьНазначенияОтветственных);
	НастройкаКопированияВерсии.Вставить("СоздатьНовыйПлан", ИсточникДанных.СоздатьНовыйПлан);
	НастройкаКопированияВерсии.Вставить("План", ИсточникДанных.План);
	НастройкаКопированияВерсии.Вставить("ЗначенияЗаполненияНовогоПлана", ЗначенияЗаполненияНовогоПлана);

	Возврат НастройкаКопированияВерсии;

КонецФункции

&НаКлиенте
Функция НастройкиКопированияВерсий()

	НастройкиКопированияВерсий = Новый Соответствие;

	Если ВерсияВШапке Тогда
		НастройкаКопированияВерсии = НастройкаКопированияВерсии(ЭтотОбъект);
		НастройкиКопированияВерсий.Вставить(ВерсияПланаИсточник, НастройкаКопированияВерсии);
	Иначе
		Для Каждого Настройка Из НастройкиКопирования Цикл
			Если Не Настройка.Пометка Тогда
				Продолжить;
			КонецЕсли;
			НастройкаКопированияВерсии = НастройкаКопированияВерсии(Настройка);
			НастройкиКопированияВерсий.Вставить(Настройка.ВерсияПланаИсточник, НастройкаКопированияВерсии);
		КонецЦикла;
	КонецЕсли;

	Возврат НастройкиКопированияВерсий;

КонецФункции

&НаКлиенте
Процедура УстановитьЗначениеВКолонкеНастроек(Значение, ИмяКолонки = "Пометка")
	Для Каждого СтрокаНастройки Из НастройкиКопирования Цикл
		СтрокаНастройки[ИмяКолонки] = Значение;
	КонецЦикла;
КонецПроцедуры

&НаКлиентеНаСервереБезКонтекста
Процедура УстановитьНастройкиЭлементовФормыСоздатьНовыйПлан(Форма)

	Элементы = Форма.Элементы;
	Элементы.План.Доступность = Не Форма.СоздатьНовыйПлан;
	Элементы.НаименованиеПлана.Доступность = Форма.СоздатьНовыйПлан;
	Элементы.ГруппаЭтоШаблон.Доступность = Форма.СоздатьНовыйПлан;

КонецПроцедуры

&НаКлиенте
Процедура ОткрытьФормуПодбораВерсии()

	ОписаниеОповещения = Новый ОписаниеОповещения("ПрименитьРезультатПодбораВерсии", 
		ЭтотОбъект);

	мИмяФормы = "Справочник.упо_Планы.Форма.ПодборПлана";
	ПараметрыОткрытия = упо_ВерсииПлановКлиент.ПараметрыОткрытияФормыПодбораВерсииСценария(ВерсииПодбора(), Владелец);

	ОткрытьФорму(мИмяФормы, 
		ПараметрыОткрытия, ЭтотОбъект, , , , ОписаниеОповещения, РежимОткрытияОкнаФормы.БлокироватьОкноВладельца);

КонецПроцедуры

&НаКлиенте
Функция ВерсииПодбора()

	ВерсииПодбора = Новый Массив;
	Для Каждого НастройкаКопирования Из НастройкиКопирования Цикл
		ВерсииПодбора.Добавить(НастройкаКопирования.ВерсияПланаИсточник);
	КонецЦикла;

	Возврат ВерсииПодбора;

КонецФункции

&НаКлиенте
Процедура ПрименитьРезультатПодбораВерсии(РезультатПодбора, ПараметрыПодбора = Неопределено) Экспорт

	Если РезультатПодбора = Неопределено Тогда
		Возврат;
	КонецЕсли;

	НастройкаЗаполненияПоУмолчанию = НастройкаЗаполненияПоУмолчанию();
	ЗаполнитьОбъектыКопированияВНастройкахКопирования(РезультатПодбора.ДанныеВыбора, НастройкаЗаполненияПоУмолчанию);

КонецПроцедуры

#КонецОбласти

#Область ОбработчикиСобытийФормы

&НаСервере
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	ЗакрыватьПриВыборе = Ложь;
	ЗаполнитьЗначенияСвойств(ЭтотОбъект, Параметры, "ЭлементУИД, ЕдиныйЭлементУИД, ВерсияПлана");
	План = ОбщегоНазначения.ЗначениеРеквизитаОбъекта(Параметры.ВерсияПлана, "План");
	ЕдиныйЭлементУИДПриОткрытии = Параметры.ЕдиныйЭлементУИД;

	УстановитьПараметрыДинамическогоСписка(СвязанныеЭлементы, Параметры);
КонецПроцедуры

&НаКлиенте
Процедура ОбработкаВыбора(ВыбранноеЗначение, ИсточникВыбора)

	ВыбранныйУИД = "";
	Если НЕ ЗначениеЗаполнено(ВыбранноеЗначение)
		ИЛИ НЕ ВыбранноеЗначение.Свойство("ЭлементУИД", ВыбранныйУИД)
		ИЛИ ВыбранныйУИД = ЭлементУИД Тогда 
		Возврат;
	КонецЕсли;

	ВыбранныйЕдиныйЭлементУИД = упо_ЕдиныеЭлементыПланаВызовСервера.ПолучитьЕдиныйЭлементУИД(ВыбранныйУИД);

	СуществующийЭлемент = СвязанныйЭлементУИД(ВерсияПлана, ВыбранныйЕдиныйЭлементУИД, ЭлементУИД);
	Если ЗначениеЗаполнено(СуществующийЭлемент) Тогда

		СообщитьСуществуетСвязанныйЭлемент(СуществующийЭлемент);	
		Возврат;
	КонецЕсли;

	ЕдиныйЭлементУИД = ВыбранныйЕдиныйЭлементУИД;

	Если ЕдиныйЭлементУИД = ЕдиныйЭлементУИДПриОткрытии Тогда
		Возврат;
	КонецЕсли;

	УстановитьПараметрыДинамическогоСпискаНаКлиенте();	

	ПараметрыЗаписи = ПараметрыЗаписиЕдиныйЭлементУИД();
	ЗаписатьДанныеВРегистры(ПараметрыЗаписи);

	ЕдиныйЭлементУИДПриОткрытии = ЕдиныйЭлементУИД;

	ВыбранноеЗначение = Новый Структура("Данные, Значение", "ЕдиныйЭлементУИД", ЕдиныйЭлементУИД);
	ОповеститьОВыборе(ВыбранноеЗначение);
КонецПроцедуры

#КонецОбласти

#Область ОбработчикиКомандФормы

&НаКлиенте
Процедура ПерепривязатьЭлемент(Команда)

	ПараметрыВыбораЭлементаПлана = Новый Структура;
	ПараметрыВыбораЭлементаПлана.Вставить("План", План);
	ПараметрыВыбораЭлементаПлана.Вставить("БлокироватьВыборВерсии", Ложь);
	ИсключаемаяВерсия = ОбщегоНазначенияКлиентСервер.ЗначениеВМассиве(ВерсияПлана);
	ПараметрыВыбораЭлементаПлана.Вставить("ИсключаемыеВерсии", ИсключаемаяВерсия);

	ПараметрыОткрытия = Новый Структура;
	ПараметрыОткрытия.Вставить("ПараметрыВыбораЭлементаПлана", ПараметрыВыбораЭлементаПлана);
	ПараметрыОткрытия.Вставить("РежимВыбораЭлементаПлана", Истина);
	ОткрытьФорму("Справочник.упо_Планы.Форма.ФормаСписка", ПараметрыОткрытия, ЭтотОбъект);		
КонецПроцедуры

&НаКлиенте
Процедура ОтвязатьЭлемент(Команда)

	ЕдиныйЭлементУИД = упо_ЭлементыСтруктурВерсийПлановВызовСервера.НовыйУникальныйИдентификаторЭлемента();	
	УстановитьПараметрыДинамическогоСпискаНаКлиенте();

	ПараметрыЗаписи = ПараметрыЗаписиЕдиныйЭлементУИД();
	ЗаписатьДанныеВРегистры(ПараметрыЗаписи, Истина);

	ЕдиныйЭлементУИДПриОткрытии = ЕдиныйЭлементУИД; // обновляем для дальнейшей работы

	ВыбранноеЗначение = Новый Структура("Данные, Значение", "ЕдиныйЭлементУИД", ЕдиныйЭлементУИД);
	ОповеститьОВыборе(ВыбранноеЗначение);
КонецПроцедуры

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаКлиентеНаСервереБезКонтекста
Процедура УстановитьПараметрыДинамическогоСписка(СвязанныеЭлементы, ПараметрыСписка)

	СвязанныеЭлементы.Параметры.УстановитьЗначениеПараметра("ЕдиныйЭлементУИД", ПараметрыСписка.ЕдиныйЭлементУИД);
	СвязанныеЭлементы.Параметры.УстановитьЗначениеПараметра("ЭлементУИД", ПараметрыСписка.ЭлементУИД);
КонецПроцедуры

&НаКлиенте
Процедура УстановитьПараметрыДинамическогоСпискаНаКлиенте()

	СтруктураПараметров = Новый Структура;
	СтруктураПараметров.Вставить("ЕдиныйЭлементУИД", ЕдиныйЭлементУИД);
	СтруктураПараметров.Вставить("ЭлементУИД", ЭлементУИД);

	УстановитьПараметрыДинамическогоСписка(СвязанныеЭлементы, СтруктураПараметров);
КонецПроцедуры

&НаСервереБезКонтекста
Функция СвязанныйЭлементУИД(ВерсияПлана, ЕдиныйЭлементУИД, ЭлементУИД)

	Запрос = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 1
	|	упо_СоответствиеЕдинымЭлементамСтруктурПланов.ЭлементУИД КАК ЭлементУИД,
	|	ЕСТЬNULL(упо_ЭлементыСтруктурПланов.Наименование, упо_СоответствиеЕдинымЭлементамСтруктурПланов.ЭлементУИД) КАК
	|		Наименование,
	|	ЕСТЬNULL(упо_ЭлементыСтруктурПланов.КодСДР, """") КАК КодСДР
	|ИЗ
	|	РегистрСведений.упо_СоответствиеЕдинымЭлементамСтруктурПланов КАК упо_СоответствиеЕдинымЭлементамСтруктурПланов
	|		ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.упо_ЭлементыСтруктурПланов КАК упо_ЭлементыСтруктурПланов
	|		ПО упо_СоответствиеЕдинымЭлементамСтруктурПланов.ЭлементУИД = упо_ЭлементыСтруктурПланов.ЭлементУИД
	|		И упо_СоответствиеЕдинымЭлементамСтруктурПланов.ВерсияПлана = упо_ЭлементыСтруктурПланов.ВерсияПлана
	|ГДЕ
	|	упо_СоответствиеЕдинымЭлементамСтруктурПланов.ЕдиныйЭлементУИД = &ЕдиныйЭлементУИД
	|	И упо_СоответствиеЕдинымЭлементамСтруктурПланов.ВерсияПлана = &ВерсияПлана
	|	И упо_СоответствиеЕдинымЭлементамСтруктурПланов.ЭлементУИД <> &ЭлементУИД");
	Запрос.УстановитьПараметр("ЭлементУИД", ЭлементУИД);
	Запрос.УстановитьПараметр("ВерсияПлана", ВерсияПлана);
	Запрос.УстановитьПараметр("ЕдиныйЭлементУИД", ЕдиныйЭлементУИД);
	Результат = Запрос.Выполнить();

	Если Результат.Пустой() Тогда 
		Возврат "";
	КонецЕсли;

	Выборка = Результат.Выбрать();
	Выборка.Следующий();
	ШаблонНаименования = "%1 (%2)";
	Наименование = СтрШаблон(ШаблонНаименования, Выборка.Наименование, Выборка.КодСДР);
	Возврат Наименование;
КонецФункции

&НаКлиенте
Процедура СообщитьСуществуетСвязанныйЭлемент(Знач СуществующийЭлемент)

	Шаблон = НСтр("ru ='В версии уже присутствует элемент связанный с выбранным: %1'");
	ТекстПредупреждения = СтроковыеФункцииКлиентСервер.ПодставитьПараметрыВСтроку(Шаблон, СуществующийЭлемент);
	ЗаголовокПредупреждения = НСтр("ru ='Не возможно привязать элемент'");

	ПоказатьПредупреждение(, ТекстПредупреждения, 5, ЗаголовокПредупреждения);
КонецПроцедуры

&НаКлиенте
Функция ПараметрыЗаписиЕдиныйЭлементУИД()

	ПараметрыЗаписи = Новый Структура;
	ПараметрыЗаписи.Вставить("План", План);
	ПараметрыЗаписи.Вставить("ЭлементУИД", ЭлементУИД);
	ПараметрыЗаписи.Вставить("ВерсияПлана", ВерсияПлана);
	ПараметрыЗаписи.Вставить("ЕдиныйЭлементУИД", ЕдиныйЭлементУИД);
	ПараметрыЗаписи.Вставить("ЕдиныйЭлементУИДПриОткрытии", ЕдиныйЭлементУИДПриОткрытии);

	Возврат ПараметрыЗаписи;
КонецФункции

&НаСервереБезКонтекста
Процедура ЗаписатьДанныеВРегистры(ПараметрыЗаписи, Отвязан = Ложь)

	ПрошлыйЕдиныйЭлементНеИспользуется = ЗначениеЗаполнено(ПараметрыЗаписи.ЕдиныйЭлементУИДПриОткрытии)
		И НЕ упо_ЕдиныеЭлементыПлана.ЕдиныйЭлементИспользуется(ПараметрыЗаписи.ЕдиныйЭлементУИДПриОткрытии,
			ПараметрыЗаписи.ЭлементУИД);

	НачатьТранзакцию();

	Попытка

		ЗаписатьСоответствиеЕдиномуЭлементу(ПараметрыЗаписи);	

		Если ПрошлыйЕдиныйЭлементНеИспользуется Тогда

			ПометитьПрошлыйЕдиныйЭлементКакНеиспользуемый(ПараметрыЗаписи);
		КонецЕсли;

		Если Отвязан Тогда

			СоздатьНовыйЕдиныйЭлементУИД(ПараметрыЗаписи);		
		КонецЕсли;

		ЗафиксироватьТранзакцию();
	Исключение

		ОтменитьТранзакцию();

		ТекстОшибки = ОбработкаОшибок.ПодробноеПредставлениеОшибки(ИнформацияОбОшибке());
		СобытиеЖР = Нстр("ru = 'Запись данных элемента'");
		ЗаписьЖурналаРегистрации(СобытиеЖР, УровеньЖурналаРегистрации.Ошибка, , ПараметрыЗаписи.ЭлементУИД, ТекстОшибки);		
	КонецПопытки;

КонецПроцедуры

&НаСервереБезКонтекста
Процедура ЗаписатьСоответствиеЕдиномуЭлементу(ПараметрыЗаписи)

	ЗаписьРегистраСоответствия = РегистрыСведений.упо_СоответствиеЕдинымЭлементамСтруктурПланов.СоздатьМенеджерЗаписи();
	ЗаполнитьЗначенияСвойств(ЗаписьРегистраСоответствия, ПараметрыЗаписи, "ЭлементУИД, ВерсияПлана, ЕдиныйЭлементУИД");
	ЗаписьРегистраСоответствия.Записать();
КонецПроцедуры

&НаСервереБезКонтекста
Процедура ПометитьПрошлыйЕдиныйЭлементКакНеиспользуемый(Знач ПараметрыЗаписи)

	ЗаписьРегистра = РегистрыСведений.упо_ЕдиныеЭлементыСтруктурПланов.СоздатьМенеджерЗаписи();
	ЗаписьРегистра.План = ПараметрыЗаписи.План;
	ЗаписьРегистра.ЕдиныйЭлементУИД = ПараметрыЗаписи.ЕдиныйЭлементУИДПриОткрытии;
	ЗаписьРегистра.Прочитать();
	ЗаписьРегистра.Используется = Ложь;
	ЗаписьРегистра.Записать();
КонецПроцедуры

&НаСервереБезКонтекста
Процедура СоздатьНовыйЕдиныйЭлементУИД(ПараметрыЗаписи)

	ЗаписьРегистра = РегистрыСведений.упо_ЕдиныеЭлементыСтруктурПланов.СоздатьМенеджерЗаписи();
	ЗаписьРегистра.План = ПараметрыЗаписи.План;
	ЗаписьРегистра.ЕдиныйЭлементУИД = ПараметрыЗаписи.ЕдиныйЭлементУИД;
	ЗаписьРегистра.Используется = Истина;
	ЗаписьРегистра.Записать();
КонецПроцедуры

#КонецОбласти

#Область ОбработчикиСобытийФормы

&НаСервере
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	упо_РаботаСФормами.УстановитьПараметрыВыбораФормыСписка(ЭтотОбъект, Параметры, "Версии");

	Если Параметры.Свойство("ОбъектПлана") Тогда

		Версии.Параметры.УстановитьЗначениеПараметра("ОбъектПлана", Параметры.ОбъектПлана);

		ПланыОбъекта = упо_ПланыОбъектовВызовСервера.ПолучитьСсылкиНаПланыОбъекта(Параметры.ОбъектПлана);
		ПринудительныйОтборПоПлану.ЗагрузитьЗначения(ПланыОбъекта);
		УстановленПринудительныйОтборПоПлану = ПринудительныйОтборПоПлану.Количество() > 0;

	ИначеЕсли Параметры.Свойство("Планы") Тогда

		Если ТипЗнч(Параметры.Планы) = Тип("Массив") Тогда
			ПринудительныйОтборПоПлану.ЗагрузитьЗначения(Параметры.Планы);
		Иначе
			ПринудительныйОтборПоПлану.Добавить(Параметры.Планы);
		КонецЕсли;

		УстановленПринудительныйОтборПоПлану = ПринудительныйОтборПоПлану.Количество() > 0;
		Версии.Параметры.УстановитьЗначениеПараметра("Планы", ПринудительныйОтборПоПлану.ВыгрузитьЗначения());

	КонецЕсли;

	УстановитьЗаголовок(ЭтаФорма);

	// СтандартныеПодсистемы.ПодключаемыеКоманды
	ПодключаемыеКоманды.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец СтандартныеПодсистемы.ПодключаемыеКоманды

	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец ИнтеграцияС1СДокументооборотом

КонецПроцедуры

