// ИнтеграцияС1СДокументооборотом
&НаКлиенте
Процедура Подключаемый_ВыполнитьКомандуИнтеграции(Команда)

	ТекущиеДанные = Элементы.Версии.ТекущиеДанные;

	Если ТекущиеДанные = Неопределено Тогда
		Возврат;
	КонецЕсли;

	Если ТекущиеДанные.Свойство("Ссылка") Тогда
		ИнтеграцияС1СДокументооборотБазоваяФункциональностьКлиент.ВыполнитьПодключаемуюКомандуИнтеграции(Команда, ЭтотОбъект, Элементы.Версии);
	Иначе
		ТекстСообщения = НСтр("ru='Действие не доступно для строки группировки списка!'");
		ОбщегоНазначенияКлиент.СообщитьПользователю(ТекстСообщения);
	КонецЕсли;

КонецПроцедуры
// Конец ИнтеграцияС1СДокументооборотом

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаКлиентеНаСервереБезКонтекста
Процедура УстановитьЗаголовок(ЭтаФорма)

	ЭтаФорма.АвтоЗаголовок = Ложь;

	Если ЭтаФорма.УстановленПринудительныйОтборПоПлану 
		И ЭтаФорма.ПринудительныйОтборПоПлану.Количество() = 1 Тогда

		СоставЗаголовка = Новый Массив;
		СоставЗаголовка.Добавить(НСтр("ru = 'Версия плана'"));
		СоставЗаголовка.Добавить(" """);
		План = ЭтаФорма.ПринудительныйОтборПоПлану[0].Значение;
		СоставЗаголовка.Добавить(Строка(План));
		СоставЗаголовка.Добавить("""");

	Иначе

		СоставЗаголовка = Новый Массив;
		СоставЗаголовка.Добавить(НСтр("ru = 'Версии планов'"));

	КонецЕсли;

	ТекстЗаголовка = СтрСоединить(СоставЗаголовка);

	ЭтаФорма.Заголовок = ТекстЗаголовка;

КонецПроцедуры

&НаСервереБезКонтекста
Процедура ЗаполнитьСпискиСценариевВСтроках(Строки)

	МассивВерсий = Новый Массив;
	Для Каждого КлючЗначение Из Строки Цикл
		Строка = КлючЗначение.Значение;
		Если Не Строка.Данные.Свойство("Ссылка") Тогда
			Продолжить;
		КонецЕсли;
		Если Не Строка.Данные.Свойство("СписокСценариев") Тогда
			Продолжить;
		КонецЕсли;
		МассивВерсий.Добавить(Строка.Данные.Ссылка);
	КонецЦикла;

	Если МассивВерсий.Количество() = 0 Тогда
		Возврат;	
	КонецЕсли;

	СоответствиеМассивов = упо_СоставСценариев.ПолучитьСоответствиеМассивовСценариевВерсий(МассивВерсий);

	МассивВерсий = Новый Массив;
	Для Каждого КлючЗначение Из Строки Цикл     
		Строка = КлючЗначение.Значение;
		Если Не Строка.Данные.Свойство("Ссылка") Тогда
			Продолжить;
		КонецЕсли;
		Если Не Строка.Данные.Свойство("СписокСценариев") Тогда
			Продолжить;
		КонецЕсли;
		МассивСценариевВерсии = СоответствиеМассивов.Получить(Строка.Данные.Ссылка);
		СписокСценариевВерсии = Новый СписокЗначений();
		СписокСценариевВерсии.ЗагрузитьЗначения(МассивСценариевВерсии);
		Строка.Данные.СписокСценариев = СписокСценариевВерсии;
	КонецЦикла;

КонецПроцедуры

&НаСервереБезКонтекста
Процедура ЗаполнитьКоличествоЭлементовПланов(Строки)

	МассивВерсий = Новый Массив;
	Для Каждого КлючЗначение Из Строки Цикл
		Строка = КлючЗначение.Значение;
		Если Не Строка.Данные.Свойство("Ссылка") Тогда
			Продолжить;
		КонецЕсли;
		Если Не Строка.Данные.Свойство("КоличествоЭлементов") Тогда
			Продолжить;
		КонецЕсли;
		МассивВерсий.Добавить(Строка.Данные.Ссылка);
	КонецЦикла;

	Если МассивВерсий.Количество() = 0 Тогда
		Возврат;	
	КонецЕсли;

	КоличествоЭлементовПоВерсиям = упо_ВерсииПланов.ПолучитьКоличествоЭлементовПоВерсиям(МассивВерсий);

	МассивВерсий = Новый Массив;
	Для Каждого КлючЗначение Из Строки Цикл     
		Строка = КлючЗначение.Значение;
		Если Не Строка.Данные.Свойство("Ссылка") Тогда
			Продолжить;
		КонецЕсли;
		Если Не Строка.Данные.Свойство("КоличествоЭлементов") Тогда
			Продолжить;
		КонецЕсли;
		КоличествоЭлементов = КоличествоЭлементовПоВерсиям.Получить(Строка.Данные.Ссылка);
		Строка.Данные.КоличествоЭлементов = КоличествоЭлементов;
	КонецЦикла;

КонецПроцедуры

&НаКлиентеНаСервереБезКонтекста
Функция ЭлементПользовательскогоОтбораПлана(ЭтаФорма)

	Возврат ЭтаФорма.Версии.КомпоновщикНастроек.ПользовательскиеНастройки.Элементы[0];	

КонецФункции

&НаСервере
Процедура ДоступностьПользовательскогоОтбораПрава()    

	ЭлементОтбора = ЭлементПользовательскогоОтбораПлана(ЭтаФорма); 

	Если УстановленПринудительныйОтборПоПлану Тогда
		ЭлементОтбора.Использование = Ложь;	
		ЭлементОтбора.РежимОтображения = РежимОтображенияЭлементаНастройкиКомпоновкиДанных.Недоступный;	
	Иначе
		ЭлементОтбора.РежимОтображения = РежимОтображенияЭлементаНастройкиКомпоновкиДанных.БыстрыйДоступ;	
	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Процедура ВключитьВерсиюВСценарий(ВерсияПлана)

	ДополнительныеПараметры = Новый Структура;
	ДополнительныеПараметры.Вставить("ВерсияПлана", ВерсияПлана);	

	ОписаниеОповещения = Новый ОписаниеОповещения("ВключитьВерсиюВСценарийЗавершение",
		ЭтотОбъект,  
		ДополнительныеПараметры);

	ТекстЗаголовка = НСтр("ru = 'Выберите сценарий планирования'");

	ПоказатьВводЗначения(ОписаниеОповещения, , ТекстЗаголовка, Тип("СправочникСсылка.упо_СценарииПланирования")); 

КонецПроцедуры  

&НаКлиенте
Процедура ВключитьВерсиюВСценарийЗавершение(Значение, ДополнительныеПараметры) Экспорт 

	Если Не ЗначениеЗаполнено(Значение) Тогда
		Возврат;
	КонецЕсли;

	ВключитьВерсиюВСценарийСервер(Значение, ДополнительныеПараметры.ВерсияПлана);	

	ОповеститьОбИзменении(ДополнительныеПараметры.ВерсияПлана);

