#Область ОбработчикиСобытийФормы

&НаСервере
Процедура ПриЧтенииНаСервере(ТекущийОбъект)

	МассивСценариев = упо_СоставСценариев.ПолучитьМассивСценариевВерсии(ТекущийОбъект.Ссылка);
	СписокСценариев.ЗагрузитьЗначения(МассивСценариев);

	ПрочитатьСвойстваВерсии(ТекущийОбъект.Ссылка);     

	ОбновитьОтображениеФормы(ЭтотОбъект);

	// СтандартныеПодсистемы.ПодключаемыеКоманды
    ПодключаемыеКомандыКлиентСервер.ОбновитьКоманды(ЭтотОбъект, Объект);
    // Конец СтандартныеПодсистемы.ПодключаемыеКоманды

	// СтандартныеПодсистемы.Свойства
	УправлениеСвойствами.ПриЧтенииНаСервере(ЭтотОбъект, ТекущийОбъект);
	// Конец СтандартныеПодсистемы.Свойства

	// упо_УправлениеПроектамиPM.СтатусыОбъектовPM
	упо_СтатусыОбъектовPM.ПриЧтенииНаСервере(ЭтотОбъект);
	// Конец упо_УправлениеПроектамиPM.СтатусыОбъектовPM

	упо_ОпцииПроектнойМодели.ФормаВладельцаПриЧтенииНаСервере(ЭтотОбъект, ТекущийОбъект);

	// СтандартныеПодсистемы.УправлениеДоступом
	Если ОбщегоНазначения.ПодсистемаСуществует("СтандартныеПодсистемы.УправлениеДоступом") Тогда
		МодульУправлениеДоступом = ОбщегоНазначения.ОбщийМодуль("УправлениеДоступом");
		МодульУправлениеДоступом.ПриЧтенииНаСервере(ЭтотОбъект, ТекущийОбъект);
	КонецЕсли;
	// Конец СтандартныеПодсистемы.УправлениеДоступом

	// Внимание! Порядок имеет значение. Вызов должен быть в конеце.
	ОграничитьДоступностьЭлементовФормы();

КонецПроцедуры

&НаСервере
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	УстановитьОграничениеТипаСпискуСценариев(ЭтотОбъект);

	Если Не ЗначениеЗаполнено(Объект.Ссылка) Тогда
		ЗаполнитьСвойстваВерсииПоУмолчанию(); 
		ОбновитьОтображениеФормы(ЭтотОбъект);
	КонецЕсли;

	// СтандартныеПодсистемы.ПодключаемыеКоманды
	ПодключаемыеКоманды.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец СтандартныеПодсистемы.ПодключаемыеКоманды

	// СтандартныеПодсистемы.Свойства
	ДополнительныеПараметры = Новый Структура;
	ДополнительныеПараметры.Вставить("ИмяЭлементаДляРазмещения", "ГруппаДополнительныеРеквизиты");
	УправлениеСвойствами.ПриСозданииНаСервере(ЭтотОбъект, ДополнительныеПараметры);
	// Конец СтандартныеПодсистемы.Свойства

	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец ИнтеграцияС1СДокументооборотом  

	// упо_УправлениеПроектамиPM.СтатусыОбъектовPM
	упо_СтатусыОбъектовPM.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец упо_УправлениеПроектамиPM.СтатусыОбъектовPM

	упо_ПроектнаяКоманда.ПриСозданииНаСервере(ЭтотОбъект, Отказ, СтандартнаяОбработка);
	КомандаВыводитьНаследуемые = Истина;

	ИнициализироватьТекущуюФазу();

	ДополнительныеПараметры = упо_ОпцииПроектнойМоделиСлужебный.КонструкторОпцииФормаВладельцаПриСозданииНаСервере();
	ДополнительныеПараметры.ИмяРодительскогоЭлементаСтраниц = "Страницы";
	упо_ОпцииПроектнойМодели.ФормаВладельцаПриСозданииНаСервере(ЭтотОбъект,
		Отказ, СтандартнаяОбработка, ДополнительныеПараметры);

	// Внимание! Порядок имеет значение. Вызов должен быть в конеце.
	ОграничитьДоступностьЭлементовФормы(Отказ);

КонецПроцедуры

&НаКлиенте
Процедура ПриОткрытии(Отказ)
	Элементы.ФормаРазрешитьРедактированиеСвойствВерсии.Пометка = Ложь;
	ОбновитьДоступностьЭлементовФормы();

	// СтандартныеПодсистемы.ПодключаемыеКоманды
    ПодключаемыеКомандыКлиент.НачатьОбновлениеКоманд(ЭтотОбъект);
    // Конец СтандартныеПодсистемы.ПодключаемыеКоманды

	// СтандартныеПодсистемы.Свойства
    УправлениеСвойствамиКлиент.ПослеЗагрузкиДополнительныхРеквизитов(ЭтотОбъект);
	// Конец СтандартныеПодсистемы.Свойства

	упо_ОпцииПроектнойМоделиКлиент.ФормаВладельцаПриОткрытии(ЭтотОбъект, Отказ);

КонецПроцедуры

&НаКлиенте
Процедура ОбработкаОповещения(ИмяСобытия, Параметр, Источник)

	// СтандартныеПодсистемы.Свойства 
	Если УправлениеСвойствамиКлиент.ОбрабатыватьОповещения(ЭтотОбъект, ИмяСобытия, Параметр) Тогда
	    ОбновитьЭлементыДополнительныхРеквизитов();
	    УправлениеСвойствамиКлиент.ПослеЗагрузкиДополнительныхРеквизитов(ЭтотОбъект);
	КонецЕсли;
	// Конец СтандартныеПодсистемы.Свойства

	Если ИмяСобытия = "ОткрытьВкладкуОбъектаДереваПланов" Тогда
		Ключ = Неопределено;
		ТекущаяСтраница = Неопределено;
		Если Не Параметр.Свойство("Ключ", Ключ) Или
			Не Параметр.Свойство("ТекущаяСтраница", ТекущаяСтраница) Тогда
			Возврат;
		КонецЕсли;

		Если Ключ = Объект.Ссылка Тогда
			ОткрытьСтраницу(ТекущаяСтраница);
		КонецЕсли;
	КонецЕсли;

КонецПроцедуры

