	ВидыСтатусовМассив = упо_СтатусыОбъектовPMВызовСервера.ПолучитьСписокВидовСтатусовНастроекСтатусов(Объект.Ссылка);

	Если ВидыСтатусовМассив.Количество() = 1 Тогда
		упо_СтатусыОбъектовPMВызовСервера.ОтменитьИзмененияСтатусовПоОбъекту(Объект.Ссылка);
		ЭтотОбъект.Прочитать();
		Возврат;
	КонецЕсли;

	ВидыСтатусовСписок = Новый СписокЗначений;
	ВидыСтатусовСписок.ЗагрузитьЗначения(ВидыСтатусовМассив);

	ОписаниеОповещения = Новый ОписаниеОповещения("ЗакончитьВыборВидаСтатуса", ЭтотОбъект);

	ВидыСтатусовСписок.ПоказатьВыборЭлемента(ОписаниеОповещения, НСтр("ru = 'Выберите вид статуса'")); 

