	ИмяТекущегоЭлемента = Команда.Имя;
	РедактируемыйУровень =
		упо_ОпцииПроектнойМоделиСлужебныйКлиент.РедактируемыйУровеньПоКонтейнеруДобавленныхЭлементовОпций(ЭтотОбъект,
			ИмяТекущегоЭлемента);
	ИмяТаблицыЗначенияОпций =
		упо_ОпцииПроектнойМоделиСлужебныйКлиент.ИмяТаблицыЗначенияОпцийПоКонтейнеруДобавленныхЭлементовОпций(ЭтотОбъект,
			ИмяТекущегоЭлемента);

	ТекущиеДанные = Элементы[ИмяТаблицыЗначенияОпций].ТекущиеДанные;
	Если ТекущиеДанные = Неопределено Тогда 
		Возврат;
	КонецЕсли;
	Если Не ЗначениеЗаполнено(ТекущиеДанные.Свойство) Тогда 
		Возврат;
	КонецЕсли;
	ПоказатьЗначение(, ТекущиеДанные.Свойство);

