	Если РезультатВопроса <> КодВозвратаДиалога.Да Тогда
		Возврат;
	КонецЕсли;

	упо_ОпцииПроектнойМоделиСлужебныйКлиент.ОбработчикКомандыОчиститьЗначениеОпцииНаТекущемУровнеЗавершение(ЭтотОбъект,
		ДополнительныеПараметры);
	ОпцииКУдалениюЗначений = ДополнительныеПараметры.ОпцииКУдалениюЗначений;
	РедактируемыйУровень = ДополнительныеПараметры.УровеньОбъекта;
	Подключаемый_ОбновитьРедактируемыеОпции(РедактируемыйУровень, , ОпцииКУдалениюЗначений);

