	ЭтоНовый = Не ЗначениеЗаполнено(Форма.Объект.Ссылка);

	Если ЭтоНовый Тогда
		СтраницаПолеПлан = Форма.Элементы.СтраницаПланВыбор;
	Иначе                                                      
		СтраницаПолеПлан = Форма.Элементы.СтраницаПланТекст;
	КонецЕсли;
	Форма.Элементы.ГруппаПолеПлан.ТекущаяСтраница = СтраницаПолеПлан;	

