&НаКлиенте
Процедура ОбновитьДоступностьЭлементовФормы()

	ДоступностьЭлементов = Элементы.ФормаРазрешитьРедактированиеСвойствВерсии.Пометка;
	Если ДоступностьЭлементов Тогда
		ВывестиПредупреждениеОРасчетеСроков();
		Элементы.ФормаРазрешитьРедактированиеСвойствВерсии.Доступность = Ложь;
	КонецЕсли;

	Элементы.ДатаОтсчета.Доступность = ДоступностьЭлементов;
	Элементы.ФормаПересчитыватьСрокиПриЗаписи.Доступность = ДоступностьЭлементов;
	Элементы.ФормаПересчитыватьСрокиПриЗаписи.Пометка = Ложь;
КонецПроцедуры

&НаКлиенте
Процедура ВывестиПредупреждениеОРасчетеСроков()

	Текст = НСтр("ru = 'При изменении параметров расчета, рекомендуется включить пересчет сроков элементов плана'");
	Заголовок = НСтр("ru = 'Внимание'");
	ПоказатьПредупреждение(, Текст, , Заголовок);
КонецПроцедуры                                                                

&НаСервере
Процедура ЗаполнитьСвойстваВерсииПоПлану()

	СтруктураВладельцев = упо_ОпцииПроектнойМодели.КонструкторСтруктурыВладельцевСвойств();
	СтруктураВладельцев.План = Объект.План; 

	Свойства = Новый Массив;
	Свойства.Добавить(ПланыВидовХарактеристик.упо_СвойстваХранилищаОпцийПроектнойМодели.Планирование);
	Свойства.Добавить(ПланыВидовХарактеристик.упо_СвойстваХранилищаОпцийПроектнойМодели.РежимРасчета);
	Свойства.Добавить(ПланыВидовХарактеристик.упо_СвойстваХранилищаОпцийПроектнойМодели.СпособРасчета);

	ЗначенияСвойств = упо_ОпцииПроектнойМодели.ПолучитьЗначенияСвойств(Свойства, СтруктураВладельцев);

	ЗначениеПоказателя = упо_ОпцииПроектнойМодели.ПолучитьЗначениеСвойстваИзТаблицыЗначенийСвойств(ЗначенияСвойств, 
		ПланыВидовХарактеристик.упо_СвойстваХранилищаОпцийПроектнойМодели.Планирование);  

	Если ЗначениеПоказателя.ЗначениеОпределено Тогда
		Планирование = ЗначениеПоказателя.Значение;
	КонецЕсли;

	ЗначениеПоказателя = упо_ОпцииПроектнойМодели.ПолучитьЗначениеСвойстваИзТаблицыЗначенийСвойств(ЗначенияСвойств, 
		ПланыВидовХарактеристик.упо_СвойстваХранилищаОпцийПроектнойМодели.РежимРасчета);  

	Если ЗначениеПоказателя.ЗначениеОпределено Тогда
		РежимРасчета = ЗначениеПоказателя.Значение;
	КонецЕсли;

	ЗначениеПоказателя = упо_ОпцииПроектнойМодели.ПолучитьЗначениеСвойстваИзТаблицыЗначенийСвойств(ЗначенияСвойств, 
		ПланыВидовХарактеристик.упо_СвойстваХранилищаОпцийПроектнойМодели.СпособРасчета);  

	Если ЗначениеПоказателя.ЗначениеОпределено Тогда
		СпособРасчета = ЗначениеПоказателя.Значение;
	КонецЕсли;	

КонецПроцедуры

&НаКлиенте
Процедура ПроверкаЗаполненияОбязательныхРеквизитов(Отказ)
	Если Не ЗначениеЗаполнено(РежимРасчета) Тогда
		Сообщение = Новый СообщениеПользователю();
		Сообщение.Текст = НСтр("ru = 'Поле ""Режим расчета"" не заполнено.'");
		Сообщение.Поле = "РежимРасчета";
		Сообщение.УстановитьДанные(ЭтотОбъект);
		Сообщение.Сообщить();
		Отказ = Истина;
	КонецЕсли; 

	Если Не ЗначениеЗаполнено(СпособРасчета) Тогда
		Сообщение = Новый СообщениеПользователю();
		Сообщение.Текст = НСтр("ru = 'Поле ""Способ расчета"" не заполнено.'");
		Сообщение.Поле = "СпособРасчета";
		Сообщение.УстановитьДанные(ЭтотОбъект);
		Сообщение.Сообщить();
		Отказ = Истина;
	КонецЕсли;

КонецПроцедуры

#Область НастройкиВыводаВСтруктуреФаз

&НаСервере
Процедура ИнициализироватьТекущуюФазу()

	ФазыИКонтрольныеТочкиДоступны = упо_УправлениеКонфигурациейКлиентСервер.ДоступноИспользованиеФазИКонтрольныхТочек();

	Элементы.ГруппаНастройкиВыводаВСтруктуреФаз.Видимость = ФазыИКонтрольныеТочкиДоступны;

	Если ФазыИКонтрольныеТочкиДоступны Тогда

		ТекущаяФаза = Объект.ТекущаяФаза;

		Опции = упо_РаботаСФормами.КонструкторОпцииНастройкиПоляЭлементПлана();
		Опции.ИмяДействияНачалоВыбора = "Подключаемый_ТекущаяФазаНачалоВыбора";
		Опции.ИмяДействияОчистка = "Подключаемый_ТекущаяФазаОчистка";
		Опции.ИмяДействияОткрытие = "Подключаемый_ТекущаяФазаОткрытие";
		Опции.Заголовок = НСтр("ru='Текущая фаза'");

		упо_РаботаСФормами.НастроитьПолеФормыЭлементПлана(ЭтотОбъект, "ТекущаяФаза", Опции);
		упо_РаботаСФормами.ЗаполнитьДопРеквизитыЭлементПлана(ЭтотОбъект, "ТекущаяФаза");

	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Функция ПараметрыФормыВыбора()

	ПараметрыФормыВыбора = Новый Структура;           
	ПараметрыФормыВыбора.Вставить("МножественныйВыбор", Ложь);
	ПараметрыФормыВыбора.Вставить("РежимВыбораЭлементаПлана", Истина); 

	ПараметрыВыбораЭлементаПлана = Новый Структура;
	ПараметрыВыбораЭлементаПлана.Вставить("ОтборЭлементовПоКонкретнойВерсии", Истина);
	ПараметрыВыбораЭлементаПлана.Вставить("БлокироватьВыборВерсии", Истина); 
	ПараметрыВыбораЭлементаПлана.Вставить("БлокироватьВыборСценария", Истина); 
	ПараметрыВыбораЭлементаПлана.Вставить("ОтборЭлементовПоКонкретнойВерсии", Истина);
	ПараметрыВыбораЭлементаПлана.Вставить("План", Объект.План);
	ПараметрыВыбораЭлементаПлана.Вставить("Версия", Объект.Ссылка);

	ПараметрыФормыВыбора.Вставить("ПараметрыВыбораЭлементаПлана", ПараметрыВыбораЭлементаПлана);

	Возврат ПараметрыФормыВыбора;

КонецФункции

&НаКлиенте
Функция ОпцииПриВыбореЭлементаПлана()

	ИмяРеквизитаЭлементУИД = "ТекущаяФаза";

	СтруктураИменРеквизитов = упо_РаботаСФормамиКлиентСервер.
		СтруктураИменРеквизитовПоШаблону(ИмяРеквизитаЭлементУИД);

	ИмяРеквизитаКартинка = СтруктураИменРеквизитов.Картинка; 
	ИмяРеквизитаПредставление = СтруктураИменРеквизитов.Представление;

	ОпцииПриВыборе = Новый Структура("Форма, ТекущиеДанные, ИмяРеквизитаЭлементУИД, ИмяРеквизитаПредставление,
	|ИмяРеквизитаКартинка, ОписаниеОповещения, ИзменяетСохраняемыеДанные, ЭтоОбъектЭлементаСтруктуры"); 
	ОпцииПриВыборе.Форма = ЭтотОбъект;
	ОпцииПриВыборе.ТекущиеДанные = ЭтотОбъект;
	ОпцииПриВыборе.ИмяРеквизитаЭлементУИД = ИмяРеквизитаЭлементУИД;
	ОпцииПриВыборе.ИмяРеквизитаПредставление = ИмяРеквизитаПредставление;
	ОпцииПриВыборе.ИмяРеквизитаКартинка = ИмяРеквизитаКартинка; 
	ОпцииПриВыборе.ИзменяетСохраняемыеДанные = Истина;
	ОпцииПриВыборе.ЭтоОбъектЭлементаСтруктуры = Ложь;
	Возврат ОпцииПриВыборе;

КонецФункции

#КонецОбласти

&НаСервере
Процедура ОграничитьДоступностьЭлементовФормы(Отказ = Неопределено)

	ОбластиПолномочий = Перечисления.упо_ОбластьПримененияПолномочий;

	ВладельцыПолномочий = упо_Полномочия.НоваяСтруктураВладельцыПолномочий();
	ВладельцыПолномочий.План = Объект.План;
	ВладельцыПолномочий.ВерсияПлана = Объект.Ссылка;
	ВладельцыПолномочий.ЦелевойВладелец = Объект.Ссылка;
	ТекущиеПолномочияПользователя = упо_Полномочия.ТекущиеПолномочияПользователя(ВладельцыПолномочий);

	ПараметрыОграниченияДоступа = ТекущиеПолномочияПользователя.РасширенныеНастройкиПоОбластямДействия;
    МассивСценариев = СписокСценариев.ВыгрузитьЗначения();

	РазрешеноРедактированиеОсновнойИнформацииПроектовПлановВерсийПланов 
	= упо_Полномочия.ЕстьДоступСогласноОбластиПрименения(ТекущиеПолномочияПользователя, 
	МассивСценариев, ОбластиПолномочий.РедактированиеОсновнойИнформацииПроектовПлановВерсийПланов);

	РазрешеноНазначениеКомандыУправленияИОтветственных = упо_Полномочия.ЕстьДоступСогласноОбластиПрименения(
	ТекущиеПолномочияПользователя, МассивСценариев, ОбластиПолномочий.НазначениеКомандыУправленияИОтветственных);

	РазрешеноИзменениеСтатусов = упо_Полномочия.ЕстьДоступСогласноОбластиПрименения(
	ТекущиеПолномочияПользователя, МассивСценариев, ОбластиПолномочий.ИзменениеСтатусов);

	РазрешеноРедактированиеДополнительныхРеквизитов = упо_Полномочия.ЕстьДоступСогласноОбластиПрименения(
	ТекущиеПолномочияПользователя, МассивСценариев, ОбластиПолномочий.РедактированиеДополнительныхРеквизитов);

	РазрешеноРедактированиеСтруктурыЭлементовПланов = упо_Полномочия.ЕстьДоступСогласноОбластиПрименения(
	ТекущиеПолномочияПользователя, МассивСценариев, ОбластиПолномочий.РедактированиеСтруктурыБюджетовРесурсовРезультатовЭлементовПланов);

	Если Параметры.Ключ.Пустая() И Не РазрешеноРедактированиеОсновнойИнформацииПроектовПлановВерсийПланов Тогда

		ТекстСообщения = НСтр("ru = 'Нет полномочий на добавление плановых данных.'");
		ОбщегоНазначения.СообщитьПользователю(ТекстСообщения,,,, Отказ);

		Возврат;

	КонецЕсли;      

	Если Не РазрешеноРедактированиеСтруктурыЭлементовПланов Тогда
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.СвойстваВерсии, Ложь);
		Элементы.ПодменюРасчет.Доступность = Ложь;
		УстановитьДоступностьКнопки("ФормаРазрешитьРедактированиеСвойствВерсии", Ложь);
	КонецЕсли;

	Если Не РазрешеноРедактированиеОсновнойИнформацииПроектовПлановВерсийПланов Тогда
		УстановитьДоступностьКнопки("ФормаУстановитьПометкуУдаления", Ложь);
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.ГруппаПолеПлан, Ложь);
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.ГруппаНаименованиеКод, Ложь);
		Элементы.Комментарий.ТолькоПросмотр = Истина;
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.ГруппаНастройкиВыводаВСтруктуреФаз, Ложь);
	КонецЕсли;

	Если Не РазрешеноРедактированиеДополнительныхРеквизитов Тогда
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.ГруппаДополнительныеРеквизиты, Ложь);
	КонецЕсли;

	Если Не РазрешеноНазначениеКомандыУправленияИОтветственных Тогда
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.СтраницаКомандаПроекта, Ложь, "КомандаВыводитьПодчиненные");
	КонецЕсли;	

	Если Не РазрешеноИзменениеСтатусов Тогда   
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.СтраницаСтатусы, Ложь);
	КонецЕсли;

КонецПроцедуры

&НаСервере
Процедура УстановитьДоступностьКнопки(ИмяКнопки, Доступность)

	Кнопка = Элементы.Найти(ИмяКнопки);
	Если Кнопка <> Неопределено Тогда
		Кнопка.Доступность = Доступность;	
	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Функция ПроверитьДоступностьВключенияИсключенияСценария(Сценарий, Отказ = Ложь)

	ИзменениеСоставаСценариевВерсий = ПараметрыОграниченияДоступа.ИзменениеСоставаСценариевВерсий;
	ВсеВерсииРазрешены = ИзменениеСоставаСценариевВерсий.ВсеВерсииРазрешены;
	Исключения = ИзменениеСоставаСценариевВерсий.Исключения;

	СвязанСНедоступнымСценарием = Ложь;
	Если ВсеВерсииРазрешены Тогда // Все разрешены, кроме...

		Если Исключения.Найти(Сценарий) <> Неопределено Тогда
			СвязанСНедоступнымСценарием	 = Истина;
		КонецЕсли;		

	Иначе // Все запрещены, кроме

		Если Исключения.Найти(Сценарий) = Неопределено Тогда
			СвязанСНедоступнымСценарием	 = Истина;
		КонецЕсли;		

	КонецЕсли;

	Если СвязанСНедоступнымСценарием Тогда
		Текст = НСтр("ru = 'Нет прав на операции со сценарием ""%1""'");
		Текст = СтрШаблон(Текст, Сценарий);
		ОбщегоНазначенияКлиент.СообщитьПользователю(Текст,,,, Отказ);
	КонецЕсли;

КонецФункции

&НаСервере
Процедура ОткрытьСтраницу(ИмяСтраницы)

	СтраницаПриОткрытии = Элементы.Страницы.ПодчиненныеЭлементы.Найти(ИмяСтраницы);
	Если СтраницаПриОткрытии <> Неопределено Тогда
		Элементы.Страницы.ТекущаяСтраница = СтраницаПриОткрытии;
	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Процедура ЗадатьВопросОЗаписиНовогоПриИзменениеКоманды(ИзменениеКоманды = Ложь)

	ОбъектНовый = ЭтотОбъект.Объект.Ссылка.Пустая();

	Если ОбъектНовый Тогда
		ДополнительныеПараметры = Новый Структура;
		ДополнительныеПараметры.Вставить("ИзменениеКоманды", ИзменениеКоманды);
		ОписаниеОЗавершении = Новый ОписаниеОповещения("ЗадатьВопросОЗаписиОбъектаПриИзменениеКомандыЗавершение", 
			ЭтаФорма,
			ДополнительныеПараметры);
		ПоказатьВопрос(ОписаниеОЗавершении, "Для продолжения необходимо записать объект. Записать?", РежимДиалогаВопрос.ДаНет);
		Возврат;	
	КонецЕсли;

	упо_ПроектнаяКомандаКлиент.ОткрытьДокументИзмененияКомандыСПараметрамиЗаполнения(ЭтотОбъект, ИзменениеКоманды);

КонецПроцедуры

&НаКлиенте
Процедура ЗадатьВопросОЗаписиОбъектаПриИзменениеКомандыЗавершение(Ответ, ДополнительныеПараметры) Экспорт

	Если Ответ = КодВозвратаДиалога.Нет Тогда
		Возврат;		
	КонецЕсли;

	ЭтотОбъект.Записать();
	упо_ПроектнаяКомандаКлиент.ОткрытьДокументИзмененияКомандыСПараметрамиЗаполнения(ЭтотОбъект, ДополнительныеПараметры.ИзменениеКоманды);	

КонецПроцедуры

&НаКлиенте
Процедура УправлениеДоступностьюКнопокКоманды()

	ТекущиеДанные = Элементы.Команда.ТекущиеДанные;
	Если ТекущиеДанные = Неопределено Тогда
		Возврат;
	КонецЕсли;

	Если Не Элементы.Команда.ТолькоПросмотр Тогда
		ЭтоКомандаТекущегоОбъекта = Не (ТекущиеДанные.ЭтоПоследователь Или ТекущиеДанные.ЭтоПредшественник);
		Элементы.КомандаИзменитьКомандуОбъекта.Доступность = ЭтоКомандаТекущегоОбъекта;
	КонецЕсли;

КонецПроцедуры

#КонецОбласти

#Область ОбработчикиСобытийФормы

&НаСервере
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	УстановитьОграничениеТипаСпискуСценариев(ЭтотОбъект);

	Параметры.Свойство("ЗначениеКопирования", КопируемаяВерсия);

	Если НужноЗагрузитьДанныеКопируемойВерсии() Тогда
		ЗагрузитьДанныеВерсии(КопируемаяВерсия);
		ЗаменитьВсеИдентификаторы();
	КонецЕсли;

	УстановитьВидимостьДоступностьЭлементов();

	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец ИнтеграцияС1СДокументооборотом

КонецПроцедуры

&НаСервере
Процедура ПриЧтенииНаСервере(ТекущийОбъект)

	МассивСценариев = упо_СоставСценариев.ПолучитьМассивСценариевВерсии(ТекущийОбъект.Ссылка);
	СписокСценариев.ЗагрузитьЗначения(МассивСценариев);

	ЗагрузитьДанныеВерсии(ТекущийОбъект.Ссылка);

	УстановитьВидимостьДоступностьЭлементов();

КонецПроцедуры

&НаСервере
Процедура ПриЗаписиНаСервере(Отказ, ТекущийОбъект, ПараметрыЗаписи)

	упо_СоставСценариев.ЗаписатьСписокСценариевВерсии(ТекущийОбъект.Ссылка, СписокСценариев);

	ЗаписатьДанныеВерсии(ТекущийОбъект);

	КопируемаяВерсия = Неопределено;

	УстановитьВидимостьДоступностьЭлементов();

КонецПроцедуры

&НаКлиенте
Процедура ПриОткрытии(Отказ)
	ПерейтиКЭлементуУИД();
КонецПроцедуры

&НаКлиенте
Процедура ПриПовторномОткрытии()
	ПерейтиКЭлементуУИД();
КонецПроцедуры

#КонецОбласти

#Область ОбработчикиСобытийЭлементовТаблицыФормыЭлементыСтруктурПланов

&НаКлиенте
Процедура ЭлементыСтруктурПлановПриНачалеРедактирования(Элемент, НоваяСтрока, Копирование)

	Если НоваяСтрока Тогда
		ПриНачалеРедактированияНовойСтрокиЭлементов();
	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Процедура ЭлементыСтруктурПлановПередОкончаниемРедактирования(Элемент, НоваяСтрока, ОтменаРедактирования, Отказ)
	Если НЕ НоваяСтрока Тогда
		Возврат;
	КонецЕсли;
	ПередОкончаниемРедактированияСтрокиЭлементов();
КонецПроцедуры

#КонецОбласти

#Область ОбработчикиСобытийЭлементовТаблицыФормыСоответствиеЕдинымЭлементамСтруктурПланов

&НаКлиенте
Процедура СоответствиеЕдинымЭлементамСтруктурПлановПриАктивизацииСтроки(Элемент)

	ТекДанные = Элементы.СоответствиеЕдинымЭлементамСтруктурПланов.ТекущиеДанные;

	Если ТекДанные = Неопределено Тогда 
		Элементы.ЕдиныеЭлементыСтруктурПланов.ОтборСтрок = Неопределено;
		Возврат;
	КонецЕсли;

	ТекущийЕдиныйЭлементУИД = ТекДанные.ЕдиныйЭлементУИД;

	Элементы.ЕдиныеЭлементыСтруктурПланов.ОтборСтрок = 
		Новый ФиксированнаяСтруктура("ЕдиныйЭлементУИД", ТекущийЕдиныйЭлементУИД);

КонецПроцедуры

#КонецОбласти

#Область ОбработчикиКомандФормы

&НаКлиенте
Процедура КомандаЗаменитьИдентификаторВыбранногоЭлементаНовым(Команда)

	Для Каждого ВыделеннаяСтрока Из Элементы.ЭлементыСтруктурПланов.ВыделенныеСтроки Цикл	

		СтрокаТаблицы = ЭлементыСтруктурПланов.НайтиПоИдентификатору(ВыделеннаяСтрока);

		Если СтрокаТаблицы = Неопределено Тогда
			Продолжить;
		КонецЕсли;

		ЗаменитьИдентификаторВыбранногоЭлементаНовым(ЭтотОбъект, СтрокаТаблицы);

	КонецЦикла;

КонецПроцедуры    

&НаКлиенте
Процедура КомандаЗадатьГоворящиеИдентификаторы(Команда)

	Префикс =  Формат(ТекущаяДата(), "ДФ=dd.MM.yyyy_H.m.s");

	сч = 1;

	Для Каждого СтрокаТаблицы Из ЭлементыСтруктурПланов Цикл        

		НовыйИдентификатор = Префикс + "_Э_" + Формат(сч, "ЧГ=");

		ЗаменитьИдентификаторВыбранногоЭлементаНовым(ЭтотОбъект, СтрокаТаблицы, НовыйИдентификатор);

		сч = сч + 1;

	КонецЦикла;

КонецПроцедуры   

&НаКлиенте
Процедура КомандаЗаписьИдентификаторВНаименование(Команда)  

	Для Каждого СтрокаТаблицы Из ЭлементыСтруктурПланов Цикл       

		СтрокаТаблицы.Наименование = СтрокаТаблицы.ЭлементУИД;

	КонецЦикла;

КонецПроцедуры    

// ИнтеграцияС1СДокументооборотом
&НаКлиенте
Процедура Подключаемый_ВыполнитьКомандуИнтеграции(Команда)

	ИнтеграцияС1СДокументооборотБазоваяФункциональностьКлиент.ВыполнитьПодключаемуюКомандуИнтеграции(Команда, ЭтотОбъект, Объект);

КонецПроцедуры
// Конец ИнтеграцияС1СДокументооборотом

&НаКлиенте
Процедура ОткрытьФормуЭлемента(Команда)    
	ТекущиеДанные = Элементы.ЭлементыСтруктурПланов.ТекущиеДанные;
	Если ТекущиеДанные = Неопределено Тогда 
		Возврат;
	КонецЕсли;
	ПослеЗакрытияФормыЭлемента = Новый ОписаниеОповещения("ЗакрытаФормаЭлемента", ЭтотОбъект);
	упо_ЭлементыСтруктурВерсийПлановКлиент.ОткрытьЭлемент(ТекущиеДанные.ЭлементУИД, ПослеЗакрытияФормыЭлемента);
КонецПроцедуры

&НаКлиенте
Процедура КомментарийНачалоВыбора(Элемент, ДанныеВыбора, СтандартнаяОбработка)

	ОбщегоНазначенияКлиент.ПоказатьФормуРедактированияКомментария(Объект.Комментарий, ЭтаФорма);

КонецПроцедуры

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаСервере
Процедура ЗагрузитьДанныеВерсии(ВерсияДляЗагрузкиДанных)

	ПрочитатьСвойстваВерсии(ВерсияДляЗагрузкиДанных);
	ЗагрузитьДанныеВНаборЗаписейНаФорме(ЭлементыСтруктурПланов, "упо_ЭлементыСтруктурПланов", ВерсияДляЗагрузкиДанных);
	ЗагрузитьДанныеВНаборЗаписейНаФорме(СрокиЭлементовСтруктурПланов, "упо_СрокиЭлементовСтруктурПланов", 
		ВерсияДляЗагрузкиДанных);
	ЗагрузитьДанныеВНаборЗаписейНаФорме(СвойстваЭлементовСтруктурПланов, "упо_СвойстваЭлементовСтруктурПланов", 
		ВерсияДляЗагрузкиДанных);
	ЗагрузитьДанныеВНаборЗаписейНаФорме(ПредшественникиЭлементовСтруктурПланов, 
		"упо_ПредшественникиЭлементовСтруктурПланов", ВерсияДляЗагрузкиДанных);
	ЗагрузитьДанныеВНаборЗаписейНаФорме(ПараметрыРасчетаЭлементовСтруктурПланов, 
		"упо_ПараметрыРасчетаЭлементовСтруктурПланов", ВерсияДляЗагрузкиДанных);
	ЗагрузитьДанныеВНаборЗаписейНаФорме(СоответствиеЕдинымЭлементамСтруктурПланов, 
		"упо_СоответствиеЕдинымЭлементамСтруктурПланов", ВерсияДляЗагрузкиДанных);
	План = упо_ОбщегоНазначенияВызовСервера.ЗначениеРеквизитаОбъекта(ВерсияДляЗагрузкиДанных, "План");
	ЗагрузитьДанныеВНаборЗаписейНаФормеПоПлану(ЕдиныеЭлементыСтруктурПланов, "упо_ЕдиныеЭлементыСтруктурПланов", План);
	ЗагрузитьДанныеВНаборЗаписейНаФорме(ГотовностьЭлементовСтруктурПланов, "упо_ГотовностьЭлементовСтруктурПланов", 
		ВерсияДляЗагрузкиДанных);   
	ЗагрузитьДанныеВНаборЗаписейНаФорме(упо_РезультатРасчетаЭлементовСтруктурПланов,
		"упо_РезультатРасчетаЭлементовСтруктурПланов", ВерсияДляЗагрузкиДанных); 	

КонецПроцедуры

&НаСервере
Процедура ЗаписатьДанныеВерсии(ТекущийОбъект)

	СохранитьСвойстваВерсии(ТекущийОбъект.Ссылка);
	ЗаписатьДанныеНабораЗаписейНаФорме(ЭлементыСтруктурПланов, "упо_ЭлементыСтруктурПланов", ТекущийОбъект.Ссылка);
	ЗаписатьДанныеНабораЗаписейНаФорме(СрокиЭлементовСтруктурПланов, "упо_СрокиЭлементовСтруктурПланов", 
		ТекущийОбъект.Ссылка);
	ЗаписатьДанныеНабораЗаписейНаФорме(СвойстваЭлементовСтруктурПланов, "упо_СвойстваЭлементовСтруктурПланов", 
		ТекущийОбъект.Ссылка);
	ЗаписатьДанныеНабораЗаписейНаФорме(ПредшественникиЭлементовСтруктурПланов, 
		"упо_ПредшественникиЭлементовСтруктурПланов", ТекущийОбъект.Ссылка);  
	ЗаписатьДанныеНабораЗаписейНаФорме(ПараметрыРасчетаЭлементовСтруктурПланов, 
		"упо_ПараметрыРасчетаЭлементовСтруктурПланов", ТекущийОбъект.Ссылка);
	ЗаписатьДанныеНабораЗаписейНаФорме(СоответствиеЕдинымЭлементамСтруктурПланов, 
		"упо_СоответствиеЕдинымЭлементамСтруктурПланов", ТекущийОбъект.Ссылка);
	ЗаписатьДанныеНабораЗаписейНаФормеПоПлану(ЕдиныеЭлементыСтруктурПланов, 
		"упо_ЕдиныеЭлементыСтруктурПланов", ТекущийОбъект.План);
	ЗаписатьДанныеНабораЗаписейНаФорме(ГотовностьЭлементовСтруктурПланов, "упо_ГотовностьЭлементовСтруктурПланов", 
		ТекущийОбъект.Ссылка);
	ЗаписатьДанныеНабораЗаписейНаФорме(упо_РезультатРасчетаЭлементовСтруктурПланов,
		"упо_РезультатРасчетаЭлементовСтруктурПланов", ТекущийОбъект.Ссылка);


КонецПроцедуры

&НаСервере
Процедура СохранитьСвойстваВерсии(ВерсияПлана)        

	СписокИнтерактивныхСвойстваВерсииСтрокой = упо_ВерсииПлановПовтИсп.СписокИнтерактивныхСвойстваВерсииСтрокой();

	ИнтерактивныеСвойства = Новый Структура(СписокИнтерактивныхСвойстваВерсииСтрокой);	

	ТекущиеЗначенияСвойствВерсии = упо_ВерсииПланов.ПолучитьИнтерактивныеСвойстваВерсииПлана(Объект.Ссылка, Истина);
	ЗаполнитьЗначенияСвойств(ИнтерактивныеСвойства, ТекущиеЗначенияСвойствВерсии);

	ЗаполнитьЗначенияСвойств(ИнтерактивныеСвойства, ЭтотОбъект); 

	ЗапускатьРасчетСроков = Ложь;
	упо_ВерсииПланов.СохранитьСвойстваВерсии(ВерсияПлана, ИнтерактивныеСвойства, ЗапускатьРасчетСроков);
