&НаКлиенте
Процедура СоздатьЕдиныйЭлементУИДИСоответствиеСНим(ЭлементУИД)                                          

	НовыйЕдиныйУИД = упо_ЭлементыСтруктурВерсийПлановВызовСервера.НовыйУникальныйИдентификаторЭлемента();

	НоваяЗаписьЕдиныйУИД = ЕдиныеЭлементыСтруктурПланов.Добавить();
	НоваяЗаписьЕдиныйУИД.ЕдиныйЭлементУИД = НовыйЕдиныйУИД;
	НоваяЗаписьЕдиныйУИД.План = Объект.План; 
	НоваяЗаписьЕдиныйУИД.ОбъектСоздан = Ложь;
	НоваяЗаписьЕдиныйУИД.Используется = Истина; 

	НоваяСвязь = СоответствиеЕдинымЭлементамСтруктурПланов.Добавить();
	НоваяСвязь.ЭлементУИД = ЭлементУИД;
	НоваяСвязь.ВерсияПлана = Объект.Ссылка;
	НоваяСвязь.ЕдиныйЭлементУИД = НовыйЕдиныйУИД;

