&НаСервере
Процедура ЗаменитьВсеИдентификаторы()

	Для Каждого СтрокаТаблицы Из ЭлементыСтруктурПланов Цикл
		ЗаменитьИдентификаторВыбранногоЭлементаНовым(ЭтотОбъект, СтрокаТаблицы);
	КонецЦикла;

КонецПроцедуры

&НаКлиентеНаСервереБезКонтекста
Процедура ЗаменитьИдентификаторВыбранногоЭлементаНовым(Форма, ОсновнаяСтрокаЭлемента, НовыйИдентификатор = Неопределено) 

	ТекущийИдентификатор = ОсновнаяСтрокаЭлемента.ЭлементУИД;

	Если НовыйИдентификатор = Неопределено Тогда
		ЗаполнитьВСтрокеУникальныйИдентификатор(ОсновнаяСтрокаЭлемента, "ЭлементУИД");
		НовыйИдентификатор = ОсновнаяСтрокаЭлемента.ЭлементУИД;
	Иначе     
		ОсновнаяСтрокаЭлемента.ЭлементУИД = НовыйИдентификатор; 
	КонецЕсли;

	ЗаменитьИдентификаторыВТаблице(Форма.ЭлементыСтруктурПланов, ТекущийИдентификатор, НовыйИдентификатор, 
		"РодительУИД");

	МассивИменТаблиц = МассивИменТаблицДанныхСИдентификатором(Ложь);

	Для Каждого ИмяТаблицы Из МассивИменТаблиц Цикл
		ТаблицаДанных = Форма[ИмяТаблицы];
		ЗаменитьИдентификаторыВТаблице(ТаблицаДанных, ТекущийИдентификатор, НовыйИдентификатор, "ЭлементУИД");
	КонецЦикла;   

	ЗаменитьИдентификаторыВТаблице(Форма.ПредшественникиЭлементовСтруктурПланов, ТекущийИдентификатор, НовыйИдентификатор, 
		"ПредшественникЭлементУИД");

КонецПроцедуры

&НаКлиентеНаСервереБезКонтекста
Функция МассивИменТаблицДанныхСИдентификатором(ВключаяОсновную = Истина) 

	Результат = Новый Массив;
	Если ВключаяОсновную Тогда
		Результат.Добавить("ЭлементыСтруктурПланов");
	КонецЕсли;
	Результат.Добавить("СвойстваЭлементовСтруктурПланов");
	Результат.Добавить("ПараметрыРасчетаЭлементовСтруктурПланов");  
	Результат.Добавить("СрокиЭлементовСтруктурПланов");
	Результат.Добавить("ПредшественникиЭлементовСтруктурПланов");
	Результат.Добавить("ГотовностьЭлементовСтруктурПланов");
	Результат.Добавить("СоответствиеЕдинымЭлементамСтруктурПланов"); 
	Результат.Добавить("упо_РезультатРасчетаЭлементовСтруктурПланов"); 

	Возврат Результат;

КонецФункции

&НаКлиентеНаСервереБезКонтекста
Процедура ЗаменитьИдентификаторыВТаблице(ТаблицаДанных, СтарыйИдентификатор, НовыйИдентификатор, ИмяПоля)

	Отбор = Новый Структура(ИмяПоля, СтарыйИдентификатор);
	НайденныеСтроки = ТаблицаДанных.НайтиСтроки(Отбор);

	Для Каждого НайденнаяСтрока Из НайденныеСтроки Цикл
		НайденнаяСтрока[ИмяПоля] = НовыйИдентификатор;
	КонецЦикла;

КонецПроцедуры

&НаКлиенте
Процедура ЗакрытаФормаЭлемента(Результат, ДополнительныеПараметры) Экспорт

	ЗагрузитьДанныеВерсии(Объект.Ссылка);

КонецПроцедуры

#КонецОбласти

#Область ОписаниеПеременных

&НаКлиенте
Перем ДеревоЭлементовПлана; // Дерево для представления элементов. Может быть передано из формы-владельца

#КонецОбласти

#Область ОбработчикиСобытийФормы

&НаСервере
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	Если Не Параметры.Свойство("ОбъектФормы", ОбъектФормы)
		Или РольДоступна(Метаданные.Роли.упо_ЗапретРедактированияЭлементаПлана) Тогда
		ТекстСообщения = нСтр("ru='Профилем доступа установлен запрет на редактирование элементов плана.'", "ru");
		ОбщегоНазначенияКлиентСервер.СообщитьПользователю(ТекстСообщения);
		Отказ = Истина;
		Возврат;
	КонецЕсли;                

	ДоступноОткрытиеРедактораПланов = Параметры.Свойство("ДоступноОткрытиеРедактораПланов") 
		И Параметры.ДоступноОткрытиеРедактораПланов;        	
	Элементы.ФормаКомандаОткрытьРедакторПлана.Видимость = ДоступноОткрытиеРедактораПланов;	

	ИспользуютсяВнешниеСвязи = упо_УправлениеКонфигурациейВызовСервера.ИспользуютсяВнешниеСвязи();
	Если Не ИспользуютсяВнешниеСвязи Тогда
		Элементы.СтраницаВнешниеПредшественники.Видимость = Ложь;
		Элементы.СтраницаВнешниеПоследователи.Видимость = Ложь;
		Элементы.СтраницыСвязей.ОтображениеСтраниц = ОтображениеСтраницФормы.Нет;
	КонецЕсли;

	ЗаголовокКомандыЗаписатьИЗакрыть = "";
	Если Параметры.Свойство("ЗаголовокКомандыЗаписатьИЗакрыть", ЗаголовокКомандыЗаписатьИЗакрыть) 
		И ЗначениеЗаполнено(ЗаголовокКомандыЗаписатьИЗакрыть) Тогда

		Элементы.ФормаКомандаЗаписатьИЗакрыть.Заголовок = ЗаголовокКомандыЗаписатьИЗакрыть;
	КонецЕсли;

	Если Параметры.Свойство("ПересчитыватьСрокиВФорме") Тогда
		ПересчитыватьСрокиВФорме = Параметры.ПересчитыватьСрокиВФорме;
	Иначе
		ПересчитыватьСрокиВФорме = Истина;
	КонецЕсли;

	ДоступноРедактированиеСтраницыСроков = Истина;
	Если Параметры.Свойство("ДоступноРедактированиеСтраницыСроков") Тогда
		ДоступноРедактированиеСтраницыСроков = Параметры.ДоступноРедактированиеСтраницыСроков;
	КонецЕсли;
	Элементы.Сроки.ТолькоПросмотр = Не ДоступноРедактированиеСтраницыСроков;
	Элементы.ИзменениеСроков_Текст.Видимость = Не ДоступноРедактированиеСтраницыСроков; 

	ВладелецФормыМожетВернутьДеревоЭлементов = Ложь;
	Если Параметры.Свойство("ВладелецФормыМожетВернутьДеревоЭлементов") Тогда
		ВладелецФормыМожетВернутьДеревоЭлементов = Параметры.ВладелецФормыМожетВернутьДеревоЭлементов;
	КонецЕсли;

	Если Параметры.Свойство("ЭлементыПланаСИдентификаторами") Тогда
		ЭлементыПланаСИдентификаторами = Параметры.ЭлементыПланаСИдентификаторами;
	КонецЕсли;

	МассивЭлементовПлана = Новый ФиксированныйМассив(Параметры.МассивЭлементовПлана);

	НастроитьСвойстваЭлементовСтруктурПлановКлючАналитикиРеквизиты();

	// Перед заполнением ключа аналитики надо его заполнить на форме.
	ЭлементПлана = ОбъектФормы.ЭлементПлана;
	Если ЭлементПлана.Свойство("КлючАналитики") Тогда
		КлючАналитики = ЭлементПлана.КлючАналитики;
	КонецЕсли;
	ЗаполнитьСвойстваЭлементовСтруктурПлановКлючАналитикиРеквизиты();
	ЗаполнитьФормуПоЕдиныйЭлементУИД(ОбъектФормы.ЭлементПлана.ЕдиныйЭлементУИД);

	Если Отказ Тогда
		Возврат;
	КонецЕсли;

	ИнициализироватьОписанияДопРеквизитовИСведений();

	ИмяАктивногоЭлемента = "";
	УказанАктивируемыйЭлементФормы = Параметры.Свойство("ТекущийЭлементФормы", ИмяАктивногоЭлемента)
		И ЗначениеЗаполнено(ИмяАктивногоЭлемента);
	Если УказанАктивируемыйЭлементФормы Тогда
		ТекущийЭлемент = Элементы[ИмяАктивногоЭлемента];
	КонецЕсли;

	ЗакрыватьПриВыборе = Ложь;

	ПараметрыРазмещения = ПодключаемыеКоманды.ПараметрыРазмещения();
	ИсточникиРазмещения = Новый Массив();
	ИсточникиРазмещения.Добавить(Метаданные.Справочники.упо_ОбъектыЕдиныхЭлементовСтруктурПланов);
	ИсточникиРазмещения.Добавить(Метаданные.Справочники.упо_ОбъектыЭлементовСтруктурВерсийПланов);
	ПараметрыРазмещения.Источники = ИсточникиРазмещения;
	// СтандартныеПодсистемы.ПодключаемыеКоманды
	ПодключаемыеКоманды.ПриСозданииНаСервере(ЭтотОбъект, ПараметрыРазмещения);
	// Конец СтандартныеПодсистемы.ПодключаемыеКоманды

	// СтандартныеПодсистемы.Свойства
	ДополнительныеПараметры = Новый Структура;
	ДополнительныеПараметры.Вставить("ИмяЭлементаДляРазмещения", "ГруппаДополнительныеРеквизиты");
	ДополнительныеПараметры.Вставить("ОтложеннаяИнициализация", Истина);
	УправлениеСвойствами.ПриСозданииНаСервере(ЭтотОбъект, ДополнительныеПараметры);
	// Конец СтандартныеПодсистемы.Свойства 

	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.ПриСозданииНаСервере(ЭтотОбъект);
	// Конец ИнтеграцияС1СДокументооборотом

	НастроитьВидимостьДоступныхЭлементовФормы();

	Элементы.ФормаРазрешитьМенятьСлужебныеСвойства.Видимость = Ложь;

КонецПроцедуры

&НаСервере
Процедура ОбработкаПроверкиЗаполненияНаСервере(Отказ, ПроверяемыеРеквизиты)

	// СтандартныеПодсистемы.Свойства
	УправлениеСвойствами.ОбработкаПроверкиЗаполнения(ЭтотОбъект, Отказ, ПроверяемыеРеквизиты);
	// Конец СтандартныеПодсистемы.Свойства
КонецПроцедуры

&НаКлиенте
Процедура ПриОткрытии(Отказ)

	ЗаполнитьФормуПоОписаниюЭлемента(Отказ);
	УстановитьЗаголовок(ЭтотОбъект);
	ОбновитьВидимостьДатыОграничения();
	ОпределитьДоступностьПолейСроков();

	ПредставлениеПланаИВерсии = ПодготовитьПредставлениеПланаИВерсии(План, ВерсияПлана);
	Элементы.ПредставлениеВерсииИПлана.Заголовок = ПредставлениеПланаИВерсии;

	ИспользуютсяМногоуровневыеПланы = упо_УправлениеКонфигурациейВызовСервера.ИспользуютсяМногоуровневыеПланы();
	Элементы.ВерхнеуровневаяЗадачаПредставление.Видимость = ИспользуютсяМногоуровневыеПланы;

	// СтандартныеПодсистемы.ПодключаемыеКоманды
    ПодключаемыеКомандыКлиент.НачатьОбновлениеКоманд(ЭтотОбъект);
    // Конец СтандартныеПодсистемы.ПодключаемыеКоманды

	// СтандартныеПодсистемы.Свойства
	УправлениеСвойствамиКлиент.ПослеЗагрузкиДополнительныхРеквизитов(ЭтотОбъект);
	// Конец СтандартныеПодсистемы.Свойства	   

	Если ВладелецФормыМожетВернутьДеревоЭлементов Тогда
		ИнициализироватьЗначенияДополнительныхРеквизитовИСвойств();
	КонецЕсли;

	ОбновитьЭлементыДлительности();

	ОграничитьДоступностьЭлементовФормы();

КонецПроцедуры

&НаКлиенте
Процедура ОбработкаОповещения(ИмяСобытия, Параметр, Источник)

	Если ИмяСобытия = "СозданОбъектЕдиногоЭлемента" И Параметр.ЭлементУИД = ЭлементУИД Тогда
		ЕдиныйЭлементУИДПриОткрытии = ЕдиныйЭлементУИД;
		ЗаполнитьФормуПоЕдиныйЭлементУИД(ЕдиныйЭлементУИДПриОткрытии);
		Возврат;
	КонецЕсли;

	// СтандартныеПодсистемы.Свойства 
	Если УправлениеСвойствамиКлиент.ОбрабатыватьОповещения(ЭтотОбъект, ИмяСобытия, Параметр) Тогда
		ОбновитьЭлементыДополнительныхРеквизитов();
		УправлениеСвойствамиКлиент.ПослеЗагрузкиДополнительныхРеквизитов(ЭтотОбъект);
	КонецЕсли;
	// Конец СтандартныеПодсистемы.Свойства
КонецПроцедуры

&НаКлиенте
Процедура ОбработкаВыбора(ВыбранноеЗначение, ИсточникВыбора)

	Если Не ЗначениеЗаполнено(ВыбранноеЗначение) Или ТипЗнч(ВыбранноеЗначение) <> Тип("Структура")
		Или Не ВыбранноеЗначение.Свойство("Данные") Тогда
		Возврат;
	КонецЕсли;

	ОбработатьВыборДляФормы(ВыбранноеЗначение);
КонецПроцедуры

&НаКлиенте
Процедура ПередЗакрытием(Отказ, ЗавершениеРаботы, ТекстПредупреждения, СтандартнаяОбработка)

	Если ЗавершениеРаботы Тогда
		Возврат;
	КонецЕсли;

	Если Не Модифицированность Тогда
		Возврат;
	КонецЕсли;

	Если ОтветПередЗакрытием = 0 Тогда

		Отказ = Истина;
		ПослеВопросаПриЗакрытииФормы = Новый ОписаниеОповещения("ПослеВопросаПриЗакрытииФормы", ЭтотОбъект);
		ТекстВопроса = НСтр("ru = 'Данные были изменены, закрыть форму без сохранения?'");
		ПоказатьВопрос(ПослеВопросаПриЗакрытииФормы, ТекстВопроса, РежимДиалогаВопрос.ДаНет);

	ИначеЕсли ОтветПередЗакрытием = 1 Тогда

		Отказ = Истина;
		ОтветПередЗакрытием = 0;

	КонецЕсли;

КонецПроцедуры

