&НаКлиенте
Процедура ВидЭлементаНачалоВыбора(Элемент, ДанныеВыбора, ВыборДобавлением, СтандартнаяОбработка)

	СтандартнаяОбработка = Ложь;

	МассивВидовЭлемента = упо_ВидыЭлементовСтруктурПлановВызовСервера.ВидыЭлементовПлана(ЭтотОбъект.ВерсияПлана);

	Отбор = Новый Структура(); 
	Отбор.Вставить("Ссылка", МассивВидовЭлемента);
	ПараметрыФормы = Новый Структура("Отбор", Отбор);

	Оповещение = Новый ОписаниеОповещения("ВыборВидаЭлементаОкончаниеВыбора", ЭтотОбъект);

	ОткрытьФорму("Справочник.упо_ВидыЭлементовСтруктурПланов.ФормаВыбора", ПараметрыФормы, 
		, 
		, 
		, 
		, 
		Оповещение); 

