#Область ОбработчикиСобытийЭлементовТаблицыФормыПСЭ_Предшественники

&НаКлиенте
Процедура ПредшественникиНаименованиеПриИзменении(Элемент)

	ТекущиеДанные  = Элементы.ПСЭ_Предшественники.ТекущиеДанные;
	ТекущиеДанные.ПредшественникУИД = ТекущиеДанные.Наименование;
	ТекущиеДанные.Наименование = ЭлементыПланаСИдентификаторами.УИД_Наименование.Получить(ТекущиеДанные.Наименование);
КонецПроцедуры

&НаКлиенте
Процедура ПредшественникиПриНачалеРедактирования(Элемент, НоваяСтрока, Копирование)

	Если НоваяСтрока И Не Копирование Тогда
		ЕдиницаВремениПоУмолчанию = упо_МенеджерФормыЭлементаПланаКлиентСервер.ЕдиницаВремениПоУмолчанию();
		Элемент.ТекущиеДанные.ЕдиницаВремениСмещения = ЕдиницаВремениПоУмолчанию;
	КонецЕсли;  
	Модифицированность = Истина;
КонецПроцедуры

&НаКлиенте
Процедура ПредшественникиНаименованиеНачалоВыбора(Элемент, ДанныеВыбора, СтандартнаяОбработка)

	ПараметрыВыбораЭлементаПлана = Новый Структура;
	ПараметрыВыбораЭлементаПлана.Вставить("План", План);
	ПараметрыВыбораЭлементаПлана.Вставить("Версия", ВерсияПлана);
	ПараметрыВыбораЭлементаПлана.Вставить("БлокироватьВыборВерсии", Истина);
	ПараметрыВыбораЭлементаПлана.Вставить("МассивЭлементовПлана", МассивЭлементовПлана);

	Если ДеревоЭлементовПлана <> Неопределено Тогда
		Колонки = "Наименование, ЭлементУИД, Родитель, ВидЭлемента, ЕдиныйЭлементУИД";
		УпакованноеДеревоЭлементовПлана = упо_УпакованноеДеревоКлиентСервер.Упаковать(ДеревоЭлементовПлана, Колонки);
		ПараметрыВыбораЭлементаПлана.Вставить("УпакованноеДеревоЭлементовПлана", УпакованноеДеревоЭлементовПлана);
	КонецЕсли;

	ПараметрыОткрытия = Новый Структура;
	ПараметрыОткрытия.Вставить("ПараметрыВыбораЭлементаПлана", ПараметрыВыбораЭлементаПлана);
	ПараметрыОткрытия.Вставить("РежимВыбораЭлементаПлана", Истина);
	ОткрытьФорму("Справочник.упо_Планы.Форма.ФормаСписка", ПараметрыОткрытия, Элементы.ПСЭ_Предшественники);
КонецПроцедуры

&НаКлиенте
Процедура ПредшественникиОбработкаВыбора(Элемент, ВыбранноеЗначение, СтандартнаяОбработка)

	Если Не ЗначениеЗаполнено(ВыбранноеЗначение) Тогда
		Возврат;
	КонецЕсли;

	// Проверим, нет ли такого элемента в таблице
	Отбор = Новый Структура("ПредшественникУИД", ВыбранноеЗначение.ЭлементУИД);
	Строки = ПСЭ_Предшественники.НайтиСтроки(Отбор);

	Если Строки.Количество() > 0 Тогда
		Возврат;
	КонецЕсли;

	ЗаполнитьСтрокуПоВыбранномуЗначению(ВыбранноеЗначение);
КонецПроцедуры

