// ИнтеграцияС1СДокументооборотом
&НаКлиенте
Процедура Подключаемый_ВыполнитьКомандуИнтеграции(Команда)

	Если НЕ ЗначениеЗаполнено(ОбъектЕдиногоЭлементаПлана) Тогда
		Если упо_ЕдиныеЭлементыПланаКлиент.СоздатьОбъектСправочникаНаФормеИсточнике(ЭтотОбъект) Тогда
			ПараметрыОповещения = Новый Структура;
			ПараметрыОповещения.Вставить("ЭлементУИД", ЭлементУИД);
			Оповестить("СозданОбъектЕдиногоЭлемента", ПараметрыОповещения);
		Иначе
			Возврат;
		КонецЕсли;
	КонецЕсли;

	ИнтеграцияС1СДокументооборотБазоваяФункциональностьКлиент.ВыполнитьПодключаемуюКомандуИнтеграции(Команда, ЭтотОбъект, Объект);

КонецПроцедуры
// Конец ИнтеграцияС1СДокументооборотом

&НаКлиенте
Процедура КомандаЗаписать(Команда)

	ОбщегоНазначенияКлиент.СообщитьПользователю("Пока не работает, используйте ""Записать и закрыть""");
	Возврат;
КонецПроцедуры

&НаКлиенте
Процедура ДополнительныеСведения(Команда)

	ПараметрыОткрытияФормы = Новый Структура;

	ПараметрыОткрытияФормы.Вставить("ТолькоПросмотр", 
	(Не РазрешеноРедактированиеДополнительныхРеквизитов 
	Или ОграниченоРедактированиеПлановыхДанных));

	Если Не ВладелецФормыМожетВернутьДеревоЭлементов Тогда
		Модифицированность = Истина;
		Если Не ЗначениеЗаполнено(ОбъектЕдиногоЭлементаПлана) Тогда
			СоздатьОбъектЕдиногоЭлемента(ЕдиныйЭлементУИД);
		КонецЕсли;
	Иначе
		ПараметрыОткрытияФормы.Вставить("ДопСвойства", ДополнительныеСвойства);
	КонецЕсли;

	ИнициализироватьЗначенияДополнительныхРеквизитовИСвойств();

	ОписаниеОповещения = Новый ОписаниеОповещения("ДополнительныеСведенияЗавершение", ЭтотОбъект);

	ПараметрыОткрытияФормы.Вставить("Ссылка", ОбъектЕдиногоЭлементаПлана);
	ОткрытьФорму("ОбщаяФорма.РедактированиеДополнительныхСведений", ПараметрыОткрытияФормы, , , , , ОписаниеОповещения);

КонецПроцедуры

&НаКлиенте
Процедура ПоказатьИдентификаторЭлемента(Команда)

	Элементы.ЭлементУИД.Видимость = Не Элементы.ЭлементУИД.Видимость;
	Элементы.ЕдиныйЭлементУИД.Видимость = Элементы.ЭлементУИД.Видимость;
	Элементы.ФормаПоказатьИдентификаторЭлемента.Пометка = Не Элементы.ФормаПоказатьИдентификаторЭлемента.Пометка;
КонецПроцедуры

