#Область ОформлениеРасчетныхПолей

&НаКлиенте
Процедура ОформитьКолонкиЗависимыеОтДругихЗадач()

	ОформляемыеЭлементы = ПолучитьПереченьЗависимыхОтДругихЗадачЭлементовФормы();
	ЦветДляОформления = ПолучитьЦветВажного();

	Для Каждого ОписаниеОформляемогоЭлемента Из ОформляемыеЭлементы Цикл

		ЭлементФормы = ОписаниеОформляемогоЭлемента.Ключ;
		ОформляемоеСвойство = ОписаниеОформляемогоЭлемента.Значение;

		Если ОформляемоеСвойство = "Рамка" Тогда
			ЭлементФормы.ЦветРамки = ЦветДляОформления;
		ИначеЕсли ОформляемоеСвойство = "Текст" Тогда
			ЭлементФормы.ЦветТекста = ЦветДляОформления;
		ИначеЕсли ОформляемоеСвойство = "Видимость" Тогда
			ЭлементФормы.Видимость = Истина;
		Иначе
			Продолжить;
		КонецЕсли;

	КонецЦикла;

КонецПроцедуры

&НаКлиенте
Функция ПолучитьПереченьЗависимыхОтДругихЗадачЭлементовФормы()

	ЭлементыНаФорме = Новый Соответствие;    
	Рамка = "Рамка";
	ЭлементыНаФорме.Вставить(Элементы.РаннееНачало, Рамка);
	ЭлементыНаФорме.Вставить(Элементы.РаннееОкончание, Рамка);
	ЭлементыНаФорме.Вставить(Элементы.ПозднееНачало, Рамка);
	ЭлементыНаФорме.Вставить(Элементы.ПозднееОкончание, Рамка);
	ЭлементыНаФорме.Вставить(Элементы.НаКритическомПути, "Текст");
	ЭлементыНаФорме.Вставить(Элементы.ПояснениеКРасчетуСроков, "Видимость");

	Возврат ЭлементыНаФорме;
КонецФункции

