&НаКлиенте
Процедура ИнициализироватьЗначенияДополнительныхСвойствНаФорме()

	ОписанияДопСвойств = ДополнительныеСвойства.ОписанияСвойств;

	Для Каждого ОписаниеДопСвойства Из ОписанияДопСвойств Цикл
		ОписаниеСвойстваИсточника = ОписаниеДопСвойства.Значение;
		Отбор = Новый Структура("Свойство", ОписаниеСвойстваИсточника.Свойство);
		СтрокиДопРеквизитов = ЭтотОбъект.Свойства_ОписаниеДополнительныхРеквизитов.НайтиСтроки(Отбор);
		Если СтрокиДопРеквизитов.Количество() Тогда
			ОписаниеДопРеквизитаНаФорме = СтрокиДопРеквизитов[0];
			ЗначениеДопРеквизитаИсточника = ОбъектФормы.ЭлементПлана[ОписаниеСвойстваИсточника.Имя];
			ЭтотОбъект[ОписаниеДопРеквизитаНаФорме.ИмяРеквизитаЗначение] = ЗначениеДопРеквизитаИсточника;
		КонецЕсли;
	КонецЦикла;

КонецПроцедуры

