КонецПроцедуры

#КонецОбласти

&НаКлиенте
Процедура ПриЗакрытииФормыУстановкиПодчиненногоПлана(РезультатЗакрытия, ДополнительныеПараметры) Экспорт

	Если РезультатЗакрытия = Неопределено Тогда
		Возврат;
	КонецЕсли;

	Если Не РезультатЗакрытия.ДанныеИзменены Тогда
		Возврат;
	КонецЕсли;

	ЗаполнитьЗначенияСвойств(ЭтотОбъект, РезультатЗакрытия);
	ПодчиненныйПланПредставление = упо_ТрансляцияДанныхКлиентСервер.ПредставлениеПодчиненногоПлана(ПодчиненныйПлан,
		ПодчиненныйСценарийПланирования, ПодчиненнаяВерсияПлана, ПодчиненныйЕдиныйЭлементУИД);

	Модифицированность = Истина;

КонецПроцедуры

&НаКлиенте
Процедура ПриЗакрытииФормыУстановкиПланаВерхнегоУровня(РезультатЗакрытия, ДополнительныеПараметры) Экспорт

	Если РезультатЗакрытия = Неопределено Тогда
		Возврат;
	КонецЕсли;

	Если Не РезультатЗакрытия.ДанныеИзменены Тогда
		Возврат;
	КонецЕсли;

	ЗаполнитьЗначенияСвойств(ЭтотОбъект, РезультатЗакрытия);
	ВерхнеуровневаяЗадачаПредставление = упо_ТрансляцияДанныхКлиентСервер.ПредставлениеПодчиненногоПлана(
		ПланВерхнегоУровня, СценарийПланированияВерхнегоУровня, ВерсияПланаВерхнегоУровня, 
		ЕдиныйЭлементУИДВерхнегоУровня);

	Модифицированность = Истина;


КонецПроцедуры

&НаКлиенте
Процедура ПослеВопросаПриЗакрытииФормы(РезультатВопроса, ДополнильныеПараметры) Экспорт

	Если РезультатВопроса = КодВозвратаДиалога.Нет Тогда
		// Не закрывать, скинуть Ответ на 0
		ОтветПередЗакрытием = 1;
	Иначе
		ОтветПередЗакрытием = 2;
	КонецЕсли;
	Закрыть();

КонецПроцедуры

&НаКлиенте
Процедура ЗаписатьИЗакрытьФорму()

	Отказ = Ложь;
	ПроверкаЗаполненияОбязательныхРеквизитов(Отказ);
	ИзмененныеСвойства = ЗаписатьДанныеЭлементаКлиент(Отказ);

	Если Отказ Тогда
		Возврат;
	КонецЕсли;

	Закрыть(ИзмененныеСвойства);
КонецПроцедуры

&НаКлиенте
Функция ПолучитьДанныеВсехДополнительныхСвойств()

	ЗначенияВсехСвойств = Новый Структура();

	Если Не ДополнительныеСвойства.Свойство("Использовать") Или Не ДополнительныеСвойства.Использовать Тогда
		Возврат ЗначенияВсехСвойств;
	КонецЕсли;

	ОписаниеДопСвойств = ДополнительныеСвойства.ОписанияСвойств;
	ЗначенияВсехСвойств = ДополнительныеСвойства.ДанныеДопСвойств;

	Для Каждого ОписаниеДопСвойства Из ОписаниеДопСвойств Цикл

		ОписаниеСвойства = ОписаниеДопСвойства.Значение;

		Если ОписаниеСвойства.ЭтоДополнительноеСведение Тогда
			Продолжить;
		КонецЕсли;

		СтруктураОтбора = Новый Структура("Свойство", ОписаниеСвойства.Свойство);
		ОписанияДопРеквизитаФормы = ЭтотОбъект.Свойства_ОписаниеДополнительныхРеквизитов.НайтиСтроки(СтруктураОтбора);
		Если ОписанияДопРеквизитаФормы.Количество() = 0 Тогда
			Значение = ОписаниеСвойства.ТипЗначения.ПривестиЗначение();
		Иначе
			Значение = ЭтотОбъект[ОписанияДопРеквизитаФормы[0].ИмяРеквизитаЗначение];
		КонецЕсли;
		ЗначенияВсехСвойств.Вставить(ОписаниеСвойства.Имя, Значение);
	КонецЦикла;

	Возврат ЗначенияВсехСвойств;

КонецФункции

&НаКлиенте
Процедура ОбработатьВыборДляТаблицыВнешнихСвязей(ИмяТаблицыСвязей, ВыбранноеЗначение, ЭтоВнешниеПредшественники)

	Если Не ЗначениеЗаполнено(ВыбранноеЗначение) Тогда
		Возврат;
	КонецЕсли;

	Если ВыбранноеЗначение.ВерсияПлана = ВерсияПлана Тогда
		Возврат;
	КонецЕсли;

	Если ЭтоВнешниеПредшественники Тогда
		ИмяПоляУИД = "ПредшественникУИД";
	Иначе
		ИмяПоляУИД = "ПоследовательУИД";
	КонецЕсли;

	ТаблицаСвязей = ЭтотОбъект[ИмяТаблицыСвязей];
	ВыбранныйУИД = ВыбранноеЗначение.ЭлементУИД;
	Отбор = Новый Структура(ИмяПоляУИД, ВыбранныйУИД);
	Строки = ТаблицаСвязей.НайтиСтроки(Отбор);

	Если Строки.Количество() > 0 Тогда
		Возврат;
	КонецЕсли;

	СтрокаТаблицы = Элементы[ИмяТаблицыСвязей].ТекущиеДанные;
	Если СтрокаТаблицы = Неопределено Тогда
		Возврат;
	КонецЕсли;

	СтрокаТаблицы[ИмяПоляУИД] = ВыбранноеЗначение.ЭлементУИДАдресации;
	СтрокаТаблицы.Наименование = ВыбранноеЗначение.Наименование;
	Если Не ЗначениеЗаполнено(СтрокаТаблицы.ТипСвязи) Тогда
		СтрокаТаблицы.ТипСвязи = упо_МенеджерФормыЭлементаПланаКлиентСервер.ТипСвязиПоУмолчанию();
	КонецЕсли;

	Если Не ЗначениеЗаполнено(СтрокаТаблицы.ЕдиницаВремениСмещения) Тогда
		СтрокаТаблицы.ЕдиницаВремениСмещения = упо_МенеджерФормыЭлементаПланаКлиентСервер.ЕдиницаВремениПоУмолчанию();
	КонецЕсли;      

	СтрокаТаблицы.ЭлементУИД = ЭлементУИД;
	ВерсияВыбранногоЭлемента = ВыбранноеЗначение.ВерсияПлана;
	ВерсияТекущегоЭлемента = ВерсияПлана;

	Если ЭтоВнешниеПредшественники Тогда
		СтрокаТаблицы.ВерсияПланаПредшественника = ВерсияВыбранногоЭлемента;
		ВыбранныйСценарий = ВыбранноеЗначение.СценарийПланирования;
		СтрокаТаблицы.СценарийПредшественника = ВыбранныйСценарий;
		СтрокаТаблицы.ВерсияПлана = ВерсияТекущегоЭлемента;
		СтрокаТаблицы.ПланПредшественника = ВыбранноеЗначение.План;
		СтрокаТаблицы.НаименованиеЭлемента = ВыбранноеЗначение.Наименование;
	Иначе
		СтрокаТаблицы.ВерсияПланаПредшественника = ВерсияТекущегоЭлемента;
		СтрокаТаблицы.ВерсияПлана = ВерсияВыбранногоЭлемента;
		СтрокаТаблицы.ПланПредшественника = План;
		СтрокаТаблицы.НаименованиеЭлемента = Наименование;
	КонецЕсли;

	ОписаниеВнешнейСвязиДляПолученияПредставления = 
		упо_МенеджерФормыЭлементаПланаКлиент.ОписаниеВнешнейСвязиДляПолученияПредставления();	
	ОписаниеВнешнейСвязиДляПолученияПредставления.ПланПредшественника = ВыбранноеЗначение.План;
	ОписаниеВнешнейСвязиДляПолученияПредставления.СценарийПредшественника = ВыбранноеЗначение.СценарийПланирования;
	ОписаниеВнешнейСвязиДляПолученияПредставления.ВерсияПланаПредшественника = ВерсияВыбранногоЭлемента;
	ОписаниеВнешнейСвязиДляПолученияПредставления.ПредшественникУИД = ВыбранноеЗначение.ЭлементУИДАдресации;

	СтрокаТаблицы.Наименование = упо_МенеджерФормыЭлементаПланаВызовСервера.ПредставлениеВнешнейСвязи(
		ОписаниеВнешнейСвязиДляПолученияПредставления);

КонецПроцедуры

