Процедура ОграничитьДоступностьЭлементовФормыДополнительныеРеквизиты()

	Если РазрешеноРедактированиеДополнительныхРеквизитов И Не ОграниченоРедактированиеПлановыхДанных Тогда
		Возврат;	
	КонецЕсли;

	упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.СтраницаДополнительныеРеквизиты, Ложь);

КонецПроцедуры

&НаСервере
Процедура ОграничитьДоступностьЭлементовФормы()

	Если Не ВладелецФормыМожетВернутьДеревоЭлементов Тогда

		СтруктураВладельцыПолномочий = упо_Полномочия.НоваяСтруктураВладельцыПолномочий();
		СтруктураВладельцыПолномочий.ЦелевойВладелец = ЭлементУИД;
		СтруктураВладельцыПолномочий.ВерсияПлана = ВерсияПлана;
		СтруктураВладельцыПолномочий.План = План;

		СценарииПланирования = упо_СценарииПланирования.СценарииВключающиеВерсиюПлана(ВерсияПлана);

		ТекущиеПолномочияПользователя = упо_Полномочия.ТекущиеПолномочияПользователя(СтруктураВладельцыПолномочий);

		РазрешеноРедактированиеСтруктурыБюджетовРесурсовРезультатов = упо_Полномочия.ЕстьДоступСогласноОбластиПрименения(ТекущиеПолномочияПользователя, 
		СценарииПланирования, Перечисления.упо_ОбластьПримененияПолномочий.РедактированиеСтруктурыБюджетовРесурсовРезультатовЭлементовПланов);

		РазрешеноРедактированиеОсновнойИнформации = упо_Полномочия.ЕстьДоступСогласноОбластиПрименения(ТекущиеПолномочияПользователя, 
		СценарииПланирования, Перечисления.упо_ОбластьПримененияПолномочий.РедактированиеОсновнойИнформацииЭлементовПланов);

		РазрешеноРедактированиеДополнительныхРеквизитов = упо_Полномочия.ЕстьДоступСогласноОбластиПрименения(ТекущиеПолномочияПользователя, 
		СценарииПланирования, Перечисления.упо_ОбластьПримененияПолномочий.РедактированиеДополнительныхРеквизитов);

		//

		СтруктураОбъектыОграничений = упо_Ограничения.НоваяСтруктураОбъектыОграничений();
		СтруктураОбъектыОграничений.ЦелевойОбъект = ЭлементУИД;

		ОграниченияОбъектаПоОбластям = упо_Ограничения.ОграниченияОбъекта(СтруктураОбъектыОграничений);

		ОбластиОграничений = Перечисления.упо_ОбластиПримененияОграничений;

		ОграниченоРедактированиеПлановыхДанных =
		упо_Ограничения.ЕстьОграниченияПоОбластиОграниченияИзТаблицыОграниченийОбъекта(ОграниченияОбъектаПоОбластям,
		ОбластиОграничений.РедактированияПлановыхДанных);

		ОграниченоРедактированиеСтатусаИГотовностиЭлементаПлана = 
		упо_Ограничения.ЕстьОграниченияПоОбластиОграниченияИзТаблицыОграниченийОбъекта(ОграниченияОбъектаПоОбластям,
		ОбластиОграничений.РедактированияСтатусаИГотовностиЭлементаПлана);

	КонецЕсли;

	Если Не РазрешеноРедактированиеСтруктурыБюджетовРесурсовРезультатов Или ОграниченоРедактированиеПлановыхДанных Тогда
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.Сроки, Ложь);
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.СтраницаЗадачиНижнегоУровня, Ложь);
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.СтраницаПредшественникиЭлементовСтруктурПланов, Ложь);
	КонецЕсли;

	Если Не РазрешеноРедактированиеОсновнойИнформации Или ОграниченоРедактированиеПлановыхДанных Тогда
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовГруппыФормыРекурсивно(Элементы.Описание, Ложь);
	КонецЕсли;

	БлокируемыеЭлементыСтраницыОсновныеДанные = БлокируемыеЭлементыСтраницыОсновныеДанные();

	ОписаниеДополнительныхРеквизитовИСведений = упо_МодельПлановВызовСервера.ПолучитьОписаниеДополнительныхРеквизитовИСведений();
	МатрицаРазрешенийСвойствЭлементовПланов = упо_МодельПлановВызовСервера.ПолучитьМатрицуРазрешенийСвойствЭлементовПланов(ОписаниеДополнительныхРеквизитовИСведений);	

	БлокируемыеЭлементы = Новый Массив;
	Для каждого ЭлементФормы Из БлокируемыеЭлементыСтраницыОсновныеДанные Цикл

		ИмяЭлемента = ЭлементФормы.Ключ;
		ПутьКДанным = ЭлементФормы.Значение;

		ЗначенияЗаполнения = Новый Структура(ПутьКДанным, Неопределено);
		РазрешеноРедактированиеРеквизита = упо_МодельПлановКлиентСервер.РазрешеноИзменениеСвойствЭлементаПланаПоМатрицеРазрешений(МатрицаРазрешенийСвойствЭлементовПланов, ЭтотОбъект, ЗначенияЗаполнения, Ложь);
		Если Не РазрешеноРедактированиеРеквизита Тогда
			БлокируемыеЭлементы.Добавить(ИмяЭлемента);			
		КонецЕсли;

	КонецЦикла;

	Если ЗначениеЗаполнено(БлокируемыеЭлементы) Тогда
		упо_ОбщегоНазначенияКлиентСервер.УстановитьДоступностьЭлементовФормы(ЭтотОбъект, БлокируемыеЭлементы, Ложь); 		
	КонецЕсли;

КонецПроцедуры

