Функция БлокируемыеЭлементыСтраницыОсновныеДанные()

	БлокируемыеЭлементы = ПолучитьЭлементыФормы(Элементы.ОсновныеДанные.ПодчиненныеЭлементы);

	// Переопределение элементов с непрямой связью со свойствами элемента плана
	БлокируемыеЭлементы.Вставить("ПодчиненныйПланПредставление", "ПредставлениеПодчиненногоПлана");
	БлокируемыеЭлементы.Вставить("ВерхнеуровневаяЗадачаПредставление", "ПредставлениеВерхнеуровневойЗадачи");

	Возврат БлокируемыеЭлементы;

КонецФункции

Функция ПолучитьЭлементыФормы(КоллекцияЭлементов, НайденныеЭлементы = Неопределено)

	Если НайденныеЭлементы = Неопределено Тогда 
		НайденныеЭлементы = Новый Соответствие;
	КонецЕсли;

	Для Каждого ЭлементФормы Из КоллекцияЭлементов Цикл

		Если ТипЗнч(ЭлементФормы) = Тип("ПолеФормы")
		   И ЭлементФормы.Вид <> ВидПоляФормы.ПолеНадписи

		 Или ТипЗнч(ЭлементФормы) = Тип("ТаблицаФормы") Тогда

			РазложенныйПутьКДанным = СтрРазделить(ЭлементФормы.ПутьКДанным, ".", Ложь);

			Если РазложенныйПутьКДанным.Количество() > 2 Тогда
				Продолжить;
			ИначеЕсли РазложенныйПутьКДанным.Количество() = 2 Тогда
				ИмяРеквизита = РазложенныйПутьКДанным[1];
			Иначе
				ИмяРеквизита = РазложенныйПутьКДанным[0];
			КонецЕсли;
			НайденныеЭлементы.Вставить(ЭлементФормы.Имя, ИмяРеквизита);
		КонецЕсли;

		Если (ТипЗнч(ЭлементФормы) = Тип("ГруппаФормы") 
			Или ТипЗнч(ЭлементФормы) = Тип("ТаблицаФормы")) Тогда

			ПолучитьЭлементыФормы(ЭлементФормы.ПодчиненныеЭлементы, НайденныеЭлементы);

		КонецЕсли;

	КонецЦикла;

	Возврат НайденныеЭлементы;

КонецФункции

