// Запускает выполнение полного расчета и запись версии плана для фонового задания
// 
// Параметры:
//  ВерсииПланов - Массив из СправочникСсылка.упо_ВерсииПланов - ссылки на пересчитываемые версии планов
//
Процедура ЗапуститьПолныйРасчетВерсииПлана(ВерсииПланов) Экспорт

	МенеджерМодели = упо_МодельПлановКлиентСервер;

	ПараметрыИнициализацииМодели = МенеджерМодели.НовыеПараметрыИнициализацииМодели();
	МодельПланов = упо_МодельПлановКлиентСервер.НоваяМодель(ПараметрыИнициализацииМодели);

	Для Каждого ВерсияПлана Из ВерсииПланов Цикл                           
		упо_МодельПлановКлиентСервер.ОткрытьПлан(МодельПланов, ВерсияПлана);
	КонецЦикла;

	упо_МенеджерРасчетаСроковКлиентСервер.РассчитатьПланыМодели(МодельПланов, Истина);
	упо_МенеджерРасчетаГотовностиКлиентСервер.РассчитатьПланыМодели(МодельПланов);

	упо_МодельПлановКлиентСервер.Записать(МодельПланов);
	упо_МодельПлановКлиентСервер.Закрыть(МодельПланов);

