Процедура ВыполнитьПересчетДлительностиИСроковЭтапов(ВерсияПлана)

	МенеджерМодели = упо_МодельПлановКлиентСервер;

	ПараметрыИнициализацииМодели = МенеджерМодели.НовыеПараметрыИнициализацииМодели();
	ПараметрыИнициализацииМодели.ИспользоватьРасчетСроков = Ложь;
	ПараметрыИнициализацииМодели.ИспользоватьРасчетГотовности = Ложь;
	МодельПланов = МенеджерМодели.НоваяМодель(ПараметрыИнициализацииМодели);
	МенеджерМодели.ОткрытьПлан(МодельПланов, ВерсияПлана);

	МенеджерМодели.НачатьОперацию(МодельПланов);

	ПеременныеРасчета = НовыеПеременныеРасчета(ВерсияПлана);
	Строки = МодельПланов.ОткрытыеПланы.Строки[0].ЭлементыПлана.Строки;
	ПолучитьСрокиЭтапа(МодельПланов, ВерсияПлана, Строки, ПеременныеРасчета);

	МенеджерМодели.ЗавершитьОперацию(МодельПланов); 

	МенеджерМодели.Записать(МодельПланов);
	МенеджерМодели.Закрыть(МодельПланов);
КонецПроцедуры

Функция НовыеПеременныеРасчета(ВерсияПлана)

	ПеременныеРасчета = Новый Структура;
	ОбщиеПроцедурыРасчета = упо_ОбщиеПроцедурыРасчетаСроковКлиентСервер;

	СвойстваВерсии = упо_ВерсииПлановВызовСервера.ПолучитьСвойстваВерсииПлана(ВерсияПлана);
	КалендарьПлана = СвойстваВерсии.КалендарьПлана;
	ПеременныеРасчета.Вставить("КалендарьПлана", КалендарьПлана);
	КалендарьПланаУИД = упо_КалендариКлиентСервер.ПолучитьИдентификаторКалендаря(КалендарьПлана);
	ПеременныеРасчета.Вставить("КалендарьПланаУИД", КалендарьПланаУИД);

	ДанныеКалендарей = ОбщиеПроцедурыРасчета.ПолучитьДанныеКалендарейВерсииПлана(ВерсияПлана, КалендарьПлана);
	ПеременныеРасчета.Вставить("ДанныеКалендарей", ДанныеКалендарей);

	ВидыЭлементов = Новый Структура;
	ВидыЭлементов.Вставить("Этап", ПредопределенноеЗначение("Справочник.упо_ВидыЭлементовСтруктурПланов.Этап"));
	ВидыЭлементов.Вставить("ПроектнаяЗадача", 
		ПредопределенноеЗначение("Справочник.упо_ВидыЭлементовСтруктурПланов.ПроектнаяЗадача"));
	ВидыЭлементов.Вставить("Веха", ПредопределенноеЗначение("Справочник.упо_ВидыЭлементовСтруктурПланов.Веха"));
	ПеременныеРасчета.Вставить("ВидыЭлементов", ВидыЭлементов);

	ПеременныеРасчета.Вставить("КэшЕдиницВремени", Новый Соответствие);
	Возврат ПеременныеРасчета;
КонецФункции

Функция ПолучитьСрокиЭтапа(МодельПланов, ВерсияПлана, Строки, ПеременныеРасчета)

	СрокиЭтапа = Новый Структура("ДатаНачала, ДатаЗавершения", Дата(3999, 12, 31), Дата(1, 1, 1));

	Для Каждого ЭлементПлана Из Строки Цикл

		ЗначенияЗаполнения = Новый Структура;

		Если ЭлементПлана.Строки.Количество() > 0 Тогда
			СрокиЭлемента = ПолучитьСрокиЭтапа(МодельПланов, ВерсияПлана, ЭлементПлана.Строки, ПеременныеРасчета);
			Если СрокиЭлемента.ДатаНачала = Дата(3999, 12, 31)
				Или СрокиЭлемента.ДатаЗавершения = Дата(1, 1, 1) Тогда

				Продолжить;
			КонецЕсли;
			ПолучитьСрокиЭтапаПоЭлементуСПодчиненными(ПеременныеРасчета, ЭлементПлана, СрокиЭлемента, СрокиЭтапа,
				ЗначенияЗаполнения);
		КонецЕсли; 

		Если ЭлементПлана.Строки.Количество() = 0 Тогда
			ПолучитьСрокиЭтапаПоЭлементуБезПодчиненных(ПеременныеРасчета, ЭлементПлана, СрокиЭтапа, ЗначенияЗаполнения);
		КонецЕсли; 

		Если ЗначенияЗаполнения.Количество() > 0 Тогда
			упо_МодельПлановКлиентСервер.ЗаполнитьСвойстваЭлементаПлана(МодельПланов, ВерсияПлана, ЭлементПлана, 
				ЗначенияЗаполнения);
		КонецЕсли;

	КонецЦикла;

	Возврат СрокиЭтапа;
КонецФункции

Процедура ПолучитьСрокиЭтапаПоЭлементуСПодчиненными(ПеременныеРасчета, ЭлементПлана, СрокиЭлемента, СрокиЭтапа, 
		ЗначенияЗаполнения)

	Если ЭлементПлана.ФиксированныеСроки Тогда

		Если ЗначениеЗаполнено(ЭлементПлана.Начало) Тогда
			СрокиЭлемента.ДатаНачала = ЭлементПлана.Начало;
		Иначе
			ЗначенияЗаполнения.Вставить("Начало", СрокиЭлемента.ДатаНачала);
		КонецЕсли;                                                          

		Если ЗначениеЗаполнено(ЭлементПлана.Завершение) Тогда
			СрокиЭлемента.ДатаЗавершения = ЭлементПлана.Завершение;
		Иначе
			ЗначенияЗаполнения.Вставить("Завершение", СрокиЭлемента.ДатаЗавершения); 
		КонецЕсли;

	Иначе
		ЗначенияЗаполнения.Вставить("Начало", СрокиЭлемента.ДатаНачала);
		ЗначенияЗаполнения.Вставить("Завершение", СрокиЭлемента.ДатаЗавершения); 
	КонецЕсли;

	ЗаполнитьСрокиЭтапа(СрокиЭтапа, СрокиЭлемента.ДатаНачала, СрокиЭлемента.ДатаЗавершения);

	РассчитатьДлительностьЭлементаПлана(ЭлементПлана, СрокиЭлемента.ДатаНачала, СрокиЭлемента.ДатаЗавершения, 
		ЗначенияЗаполнения, ПеременныеРасчета);

КонецПроцедуры

Процедура ПолучитьСрокиЭтапаПоЭлементуБезПодчиненных(ПеременныеРасчета, ЭлементПлана, СрокиЭтапа, ЗначенияЗаполнения)

	РассчитатьДлительностьЭлементаПлана(ЭлементПлана, ЭлементПлана.Начало, ЭлементПлана.Завершение, ЗначенияЗаполнения,
	ПеременныеРасчета); 
	Если ЗначениеЗаполнено(ЭлементПлана.Начало) И ЗначениеЗаполнено(ЭлементПлана.Завершение) Тогда
		ЗаполнитьСрокиЭтапа(СрокиЭтапа, ЭлементПлана.Начало, ЭлементПлана.Завершение);
	КонецЕсли;

КонецПроцедуры

Процедура ЗаполнитьСрокиЭтапа(СрокиЭтапа, Начало, Завершение)

	СрокиЭтапа.ДатаНачала = Мин(СрокиЭтапа.ДатаНачала, Начало);
	СрокиЭтапа.ДатаЗавершения = Макс(СрокиЭтапа.ДатаЗавершения, Завершение);
КонецПроцедуры

Процедура РассчитатьДлительностьЭлементаПлана(ЭлементПлана, ДатаНачала, ДатаЗавершения, ЗначенияЗаполнения, 
		ПеременныеРасчета)

	ОписаниеЕдиницыВремени = упо_ОбщиеПроцедурыРасчетаСроковКлиентСервер.ПолучитьОписаниеЕдиницыИзмерения(
	ЭлементПлана.ЕдиницаИзмеренияДлительности, ПеременныеРасчета.КэшЕдиницВремени);

	Если ЗначениеЗаполнено(ЭлементПлана.Календарь) Тогда
		КалендарьУИД = упо_КалендариКлиентСервер.ПолучитьИдентификаторКалендаря(ЭлементПлана.Календарь);
	Иначе
		КалендарьУИД = ПеременныеРасчета.КалендарьПланаУИД;
	КонецЕсли;
	ДанныеКалендаря = ПеременныеРасчета.ДанныеКалендарей.Получить(КалендарьУИД);

	Если ОписаниеЕдиницыВремени.Астрономическая Тогда
		ДлительностьВСекундах = ДатаЗавершения - ДатаНачала;
	Иначе
		ДлительностьВСекундах = упо_РасчетСроковКлиентСервер.РабочихСекундВПериоде(ДатаНачала, ДатаЗавершения, 
		ДанныеКалендаря);
	КонецЕсли;

	ДлительностьВЕдИзмерения = упо_РасчетСроковКлиентСервер.ЕдиницВремениВПериоде(ДатаНачала, ДатаЗавершения,
	ОписаниеЕдиницыВремени, ДлительностьВСекундах, ДанныеКалендаря);

	ЗаполнитьСвойствоПриНеобходимости(ЭлементПлана, "Длительность", ДлительностьВЕдИзмерения, ЗначенияЗаполнения);
	ЗаполнитьСвойствоПриНеобходимости(ЭлементПлана, "РассчитаннаяДлительностьВСекундах", ДлительностьВСекундах, 
		ЗначенияЗаполнения);
	ЗаполнитьСвойствоПриНеобходимости(ЭлементПлана, "РассчитаннаяДлительность", ДлительностьВЕдИзмерения, 
		ЗначенияЗаполнения);
	ЗаполнитьСвойствоПриНеобходимости(ЭлементПлана, "АстрономическаяДлительность", ОписаниеЕдиницыВремени.Астрономическая,
		ЗначенияЗаполнения);
КонецПроцедуры

Процедура ЗаполнитьСвойствоПриНеобходимости(ЭлементПлана, ИмяПоля, Значение, ЗначенияЗаполнения)

	Если ЭлементПлана[ИмяПоля] <> Значение Тогда
		ЗначенияЗаполнения.Вставить(ИмяПоля, Значение);
	КонецЕсли;
КонецПроцедуры

