&ИзменениеИКонтроль("ЗаполнитьСписокДоступныхРеквизитов")
Процедура упо_ЗаполнитьСписокДоступныхРеквизитов(Параметры, ИсточникиДоступныхПолей, КэшСКД)

	ИмяСпискаПолей = Параметры.ИмяСпискаПолей;
	УникальныйИдентификаторФормы = Параметры.УникальныйИдентификаторФормы;
	НастройкиСписка = Параметры.НастройкиСписка;
	ТекущийРеквизит = Параметры.ТекущийРеквизит;

	ДанныеКеша = Неопределено;
	ДоступныеРеквизиты = Неопределено;
	ТипУказан = ТипЗнч(ТекущийРеквизит) = Тип("СтрокаДереваЗначений") И ТекущийРеквизит.Тип <> Новый ОписаниеТипов();
	Если КэшСКД <> Неопределено И ТипУказан Тогда
		ОтборКэша = Новый Структура("ИмяСпискаПолей, ТипПоля", ИмяСпискаПолей, ТекущийРеквизит.Тип);
		ДанныеКеша = КэшСКД.НайтиСтроки(ОтборКэша);
		Если ДанныеКеша.Количество() > 0 Тогда
			ДоступныеРеквизиты = ДанныеКеша[0].ДоступныеПоля;
		КонецЕсли;
	КонецЕсли;

	Если ДоступныеРеквизиты = Неопределено Тогда
		КоллекцииДоступныхПолей = КоллекцииДоступныхПолей(ТекущийРеквизит, ИсточникиДоступныхПолей, НастройкиСписка, УникальныйИдентификаторФормы);
		ДоступныеРеквизиты = ДоступныеРеквизиты(КоллекцииДоступныхПолей);
		Если КэшСКД <> Неопределено И ТипУказан И ДанныеКеша.Количество() = 0 Тогда
			ДанныеКеша = КэшСКД.Добавить();
			ДанныеКеша.ИмяСпискаПолей = ИмяСпискаПолей;
			ДанныеКеша.ТипПоля = ТекущийРеквизит.Тип;
			ДанныеКеша.ДоступныеПоля = ДоступныеРеквизиты;
		КонецЕсли;
	КонецЕсли;

	КоллекцияРеквизитов = ПодчиненныеЭлементы(ТекущийРеквизит);
	ПолеСсылкаДобавлено = Ложь;
	Для Каждого ДоступныйРеквизит Из ДоступныеРеквизиты Цикл
		Если ДоступныйРеквизит.Имя = "Ссылка" Тогда
			Если ТипЗнч(ТекущийРеквизит) <> Тип("ДанныеФормыДерево") И ТипЗнч(ТекущийРеквизит) <> Тип("ДеревоЗначений")
				Или ПолеСсылкаДобавлено Тогда
				Продолжить;
			КонецЕсли;
			ПолеСсылкаДобавлено = Истина;
		КонецЕсли;

		#Вставка
		// {PM}
		Если ТипЗнч(ТекущийРеквизит) <> Тип("ДанныеФормыДерево") И ТипЗнч(ТекущийРеквизит) <> Тип("ДеревоЗначений") Тогда
			Если упо_Интеграция.КонструкторФормул_ПропуститьДобавлениеРеквизита(ТекущийРеквизит, ДоступныйРеквизит) Тогда
				Продолжить;
			Иначе
				упо_Интеграция.КонструкторФормул_КорректироватьЗаголовокРеквизита(ТекущийРеквизит, ДоступныйРеквизит);
			КонецЕсли;
		КонецЕсли;
		// {/PM}
		#КонецВставки

		Реквизит = КоллекцияРеквизитов.Добавить();
		ЗаполнитьЗначенияСвойств(Реквизит, ДоступныйРеквизит);

		Если Родитель(Реквизит) <> Неопределено Тогда
			Родитель = Родитель(Реквизит);
			Если Реквизит.ЭтоГруппа Тогда
				Реквизит.ПутьКДанным = Родитель.ПутьКДанным;
				Реквизит.ПредставлениеПутиКДанным = Строка(Родитель.ПредставлениеПутиКДанным);
			Иначе
				Если ЗначениеЗаполнено(Родитель.ПутьКДанным) Тогда
					Реквизит.ПутьКДанным = Родитель.ПутьКДанным + "." + Реквизит.Имя;
					Реквизит.ПредставлениеПутиКДанным = Строка(Родитель.ПредставлениеПутиКДанным) + "." + Реквизит.Заголовок;
				КонецЕсли;
			КонецЕсли;
		КонецЕсли;

		Если ДоступныйРеквизит.ЕстьПодчиненные Тогда
			ПодчиненныеЭлементы(Реквизит).Добавить();
		ИначеЕсли НастройкиСписка <> Неопределено И ЗначениеЗаполнено(НастройкиСписка.ПриОпределенииИсточниковДоступныхПолей) Тогда
			КоллекцииПолейРеквизита = КоллекцииДоступныхПолей(Реквизит, ИсточникиДоступныхПолей, НастройкиСписка, УникальныйИдентификаторФормы);
			Если ЗначениеЗаполнено(КоллекцииПолейРеквизита) И Не СтрНайти(Реквизит.ПутьКДанным, Реквизит.Имя + ".")
				И ЗначениеЗаполнено(КоллекцииПолейРеквизита[0].Элементы) Тогда
				ПодчиненныеЭлементы(Реквизит).Добавить();
			КонецЕсли;
		КонецЕсли;
	КонецЦикла;

КонецПроцедуры

&ИзменениеИКонтроль("ЕстьПодчиненныеЭлементы")
Функция упо_ЕстьПодчиненныеЭлементы(Знач ОписаниеПоля)

	#Вставка
	// {PM}
	ПолеСтрокой = Строка(ОписаниеПоля.Поле);
	Если СтрНайти(ПолеСтрокой, ".упо_СлужебнаяГруппаОтветственные.") > 0
		Или СтрНайти(ПолеСтрокой, ".упо_СлужебнаяГруппаПолномочия.") > 0
		Или СтрНайти(ПолеСтрокой, ".упо_СлужебнаяГруппаПроверкаНаличияПолномочий.") > 0 Тогда
		Возврат Ложь;
	КонецЕсли;
	// {/PM}
	#КонецВставки

	Если ОписаниеПоля.Папка Или ОписаниеПоля.Таблица Тогда
		Возврат Истина;
	КонецЕсли;

	Для Каждого Тип Из ОписаниеПоля.Тип.Типы() Цикл
		Если ОбщегоНазначения.ЭтоСсылка(Тип) 
			Или Тип = Тип("Дата") И ОписаниеПоля.Элементы.Количество() > 0 Тогда
			Возврат Истина;
		КонецЕсли; 
	КонецЦикла;

	#Вставка
	// {PM}
	Если ЗначениеЗаполнено(ОписаниеПоля.Элементы) Тогда
		Возврат Истина;
	КонецЕсли;
	// {/PM}
	#КонецВставки

	Возврат Ложь;

КонецФункции

