		ПараметрыГруппы.Вставить("ВыбраннаяГруппаПуста",         Ложь);
		ПараметрыГруппы.Вставить("ПредставлениеВыбраннойГруппы", НСтр("ru = 'Элемент плана'"));

		РазместитьГруппуПолейСКД(
			СтруктураЭлементовПлана, НаборДанныхКД, ГруппировкаДетальныеЗаписи, ПараметрыГруппы, ВидРегистра, ИмяРегистра);

	КонецЕсли;
	// {/PM}

	Если СтруктураИзмерений.Количество() > 0 Тогда

		ПараметрыГруппы = Новый Структура;
		ПараметрыГруппы.Вставить("ИмяГруппы",                    "Измерения");
